return ['x-generator'=>'GlotPress/4.0.1','translation-revision-date'=>'2025-01-19 20:11:52+0000','plural-forms'=>'nplurals=2; plural=n != 1;','project-id-version'=>'Plugins - WP Mail SMTP by WPForms &#8211; The Most Popular SMTP and Email Log Plugin - Stable (latest release)','language'=>'sq_AL','messages'=>['%1$s <a href="%2$s" target="_blank" rel="noopener noreferrer">Upgrade to Pro now for easy, one-click Outlook setup</a>.'=>'%1$s <a href="%2$s" target="_blank" rel="noopener noreferrer">Përmirësojeni me Pro që tani, për ujdisje të kollajtë, me një klikim për Outlook-un</a>.','Heads up! Microsoft is <a href="%1$s" target="_blank" rel="noopener noreferrer">discontinuing support for basic SMTP connections</a>. To continue using Outlook or Hotmail, switch to our Outlook mailer for uninterrupted email sending.'=>'Vini re! Microsoft-i po <a href="%1$s" target="_blank" rel="noopener noreferrer">e ndal mbulimin për lidhje elementare SMTP</a>. Që të vazhdoni përdorimin e Outlook-ut apo Hotmail-it, kaloni te postuesi ynë për Outlook, për dërgim të pandërprerë email-esh.','Follow this link to get an API Key from Elastic Email: %s.'=>'Ndiqni këtë lidhje që të merrni një Kyç API prej Elastic Email: %s.','Elastic Email'=>'Elastic Email','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Elastic Email documentation</a>.'=>'Për t’ia filluar, lexoni <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për Elastic Email</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Elastic Email</a> is a cloud-based email marketing platform offering tools for email campaigns, automation, transactional emails, and analytics, designed for businesses of all sizes.<br><br>If you\'re just starting out, you can use Elastic Email\'s free plan to send emails to your account address from one of your verified email addresses. You don\'t need to use a credit card to try it out. When you\'re ready, you can upgrade to a higher plan.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Elastic Email</a> është një platformë marketingu me email, me bazë në re, që ofron mjete për fushata me email, automatizim, email-e transaksionesh dhe statistika, për biznese të të gjitha madhësive.<br><br>Nëse sapo ia filloni, mund të përdorni planin falas të Elastic Email-it për të dërguar email-e te adresa e llogarisë suaj që nga një adresë email e juaj e verifikuar. S’ju duhet kartë krediti për ta provuar. Kur të jeni gati, mund ta përmirësoni me një plan më sipër.','One-Click Setup for Microsoft Outlook requires an active license. Verify your license to proceed with this One-Click Setup, please.'=>'Ujdisja Me Një Klikim për Microsoft Outlook lyp një licencë aktive. Ju lutemi, që të vazhdohet me Ujdisjen Me Një Klikim, verifikoni licencën tuaj.','Sign in with Outlook'=>'Bëni hyrjen me Outlook','You have successfully connected your site with your Outlook account. Now you can start sending emails through Outlook.'=>'E keni lidhur me sukses sajtin e tanishëm me llogarinë tuaj Outlook. Tani mund të filloni të dërgoni email-e përmes Outlook-ut.','Provides a quick and easy way to connect to Outlook that doesn\'t require creating your own app.'=>'Jep një rrugë të shpejtë dhe të kollajtë për t’u lidhur me Outlook-un, e cila s’lyp krijimin e një aplikacioni tuajin.','%1$sFollow this link%2$s to get an API Key for Elastic Email.'=>'%1$sNdiqni këtë lidhje%2$s që të merrni një Kyç API për Elastic Email.','Read how to set up Elastic Email'=>'Lexoni si të ujdiset Elastic Email','Remove Server API Token'=>'Hiqni Token API Shërbyesi','Follow this link to get the Secret key from Mailjet: %s.'=>'Ndiqni këtë lidhje që të merrni kyçin e Fshehtë prej Mailhet-i: %s.','Remove Secret Key'=>'Hiqe Kyçin e Fshehtë','API Key Management'=>'Administrim Kyçesh API','Follow this link to get the API key from Mailjet: %s.'=>'Ndiqni këtë lidhje që të merrni kyçin API prej Mailjet-i: %s.','Mailjet'=>'Mailjet','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Mailjet documentation</a>.'=>'Për t’ia filluar, lexoni <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për Mailjet</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailjet</a> is a cloud-based email service platform that enables businesses to send marketing and transactional emails, offering features like email automation, real-time analytics, and responsive design templates. If you\'re just starting out, you can send up to 200 emails per day without a credit card.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailjet</a> është një platformë shërbimi email, në re, që u bën të mundur bizneseve të dërgojnë email marketingu dhe transaksionesh, duke ofruar veçori të tilla si automatizim email-esh, statistika të atypëratyshme dhe gjedhe me skemë grafike reaguese. Nëse jeni në hapat e parë, mund të dërgoni deri në 200 email-e në ditë, pa ndonjë kartë krediti.','Remove API Key'=>'Hiqni Kyç API','Remove Client Secret'=>'Hiqni të Fshehtë Klienti','Discord Alerts'=>'Sinjalizime Discord','Paste in the Discord webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up Discord alerts.'=>'Hidhni këtu URL-në e webhook-ut Discord që do të donit të përdoret për të marrë sinjalizime, kur dërgimi i email-eve dështon. Se si të ujdisjen sinjalizime Discord, lexoni dokumentimin tonë.','Discord'=>'Discord','Charitable'=>'Charitable','Follow this link to get the Secret key from Mailjet: %1$sAPI Key Management%2$s.'=>'Ndiqni këtë lidhje që të merrni kyçin e Fshehtë nga Mailjet: %1$sAdministrim Kyçesh API%2$s.','Follow this link to get the API key from Mailjet: %1$sAPI Key Management%2$s.'=>'Ndiqni këtë lidhje që të merrni kyçin API nga Mailjet: %1$sAdministrim Kyçesh API%2$s.','Read how to set up Mailjet'=>'Lexoni si të ujdiset Mailjet-i','Follow this link to get an API key and Secret key from Mailjet: %1$sAPI Key Management%2$s.'=>'Ndiqni këtë lidhje që të merrni kyçin API dhe kyçin e Fshehtë nga Mailjet: %1$sAdministrim Kyçesh API%2$s.','Secret Key'=>'Kyç i Fshehtë','control panel'=>'panel kontrolli','Generate an API key on the Sending &rarr; API Keys page in your %s.'=>'Prodhoni një kyç API që nga faqja Dërgim &rarr; Kyçe API te %s juaj.','SMTP2GO'=>'SMTP2GO','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">SMTP2GO documentation</a>.'=>'Për t’ia filluar, lexoni <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për SMTP2GO</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">SMTP2GO</a> provides a robust and reliable email delivery service with global infrastructure, real-time analytics, and advanced security features. If you\'re just starting out, you can use SMTP2GO\'s free plan to send up to 1000 emails per month.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">SMTP2GO</a> jep një shërbim të fuqishëm dhe të qëndrueshëm dërgimesh email-i, me infrastrukturë globale, statistika të atypëratyshme dhe veçori të thelluara sigurie. Nëse jeni në hapat e parë, mund të përdorni planin falas të SMTP2GO-së për të dërguar deri në 1000 email-e në muaj.','Remove Password'=>'Hiqe Fjalëkalimin','Remove'=>'Hiqe','Microsoft Teams Alerts'=>'Sinjalizime Microsoft Teams','Paste in the Microsoft Teams webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up Microsoft Teams alerts.'=>'Hidhni këtu URL-në e webhook-ut Microsoft Teams që do të donit të përdoret për të marrë sinjalizime, kur dërgimi i email-eve dështon. Se si të ujdisjen sinjalizime Microsoft Teams, lexoni dokumentimin tonë.','Microsoft Teams'=>'Microsoft Teams','Read how to set up SMTP2GO'=>'Lexoni si të ujdiset SMTP2GO','Generate an API key on the Sending → API Keys page in your %1$scontrol panel%2$s.'=>'Prodhoni një kyç API që nga faqja Dërgim → Kyçe API te %1$spaneli juaj i kontrollit%2$s.','[Emails Queue] Skipped processing enqueued email. %1$s. Email ID: %2$d'=>'[Radhë Email-esh] U anashkalua përpunim email-i të vënë në radhë. %1$s. ID Email-i: %2$d','[Emails Queue] Failed to update queue record after sending email from the queue. %1$s. Email ID: %2$d'=>'[Radhë Email-esh] S’u arri të përditësohej zë radhe, pas dërgimit të email-it prej radhës. %1$s. ID Email: %2$d','[Emails Queue] Skipped email sending from the queue. Wrong email status. Email ID: %1$d, email status: %2$s.'=>'[Radhë Email-esh] U anashkalua dërgim email-i nga radha. Gjendje e gabuar email-i. ID Email-i: %1$d, gjendje email-i: %2$s.','[Emails Queue] Skipped email sending from the queue. %1$s. Email ID:  %2$s'=>'[Radhë Email-esh] U anashkalua dërgim email-i nga radha. %1$s. ID Email-i:  %2$s','[Emails Queue] Skipped email sending from the queue. Queue::send_email method was called directly. Email ID: %1$d.'=>'[Radhë Email-esh] U anashkalua dërgim email-i nga radha. Metoda Queue::send_email u thirr drejtpërdrejt. ID Email-i: %1$d.','[Emails Queue] Skipped enqueueing email. %1$s.'=>'[Radhë Email-esh] U anashkalua vënie në radhë email-i. %1$s.','Insert/update SQL query error: %1$s'=>'Gabim futjeje/përditësimi kërkese SQL: %1$s','Data JSON encoding error: %1$s'=>'Gabim kodimi JSON të dhënash: %1$s','Data JSON decoding error: %1$s'=>'Gabim shkodimi JSON të dhënash: %1$s','Invalid record format'=>'Format i pavlefshëm zërash','Record not found in DB'=>'Zëri s’u gjet në BD','The selected mailer is not compatible with your PHP version.'=>'Postuesi i përzgjedhur s’është i përputhshëm me versionin tuaj të PHP-së.','The selected mailer not found.'=>'Postuesi i përzgjedhur s’u gjet.','Yes, I\'ll rate it with 5-stars'=>'Po, do ta vlerësoj me 5 yje','That\'s fantastic! Would you consider giving it a 5-star rating on WordPress.org? It will help other users with email issues and it will mean the world to us!'=>'Fantastike! A do të mendoheshit për t’i dhënë një vlerësim me 5 yje në WordPress.org? Do të ndihmojë përdorues të tjerë me probleme email-i dhe do të vlente sa krejt bota për ne!','Provide Feedback'=>'Jepni Përshtypje','No'=>'Jo','Limit the number of emails this site will send in each time interval (per minute, hour, day, week and month). Emails that will cross those set limits will be queued and sent as soon as your limits allow. <a href="%1$s" target="_blank" rel="noopener noreferrer">Learn More</a>'=>'Kufizoni numrin e email-eve që ky sajt do të dërgojë në çdo interval kohor (për minutë, orë, ditë, javë dhe muaj). Email-et që do të kapërcejnë këta kufij të vendosur do të vihen në radhë dhe dërgohen sapo ta lejojnë kufijtë tuaj. <a href="%1$s" target="_blank" rel="noopener noreferrer">Mësoni Më Tepër</a>','Email Rate Limiting'=>'Kufizim Dërgimi Email-esh','Send emails asynchronously, which will make pages with email requests load faster, but may delay email delivery by a minute or two. <a href="%1$s" target="_blank" rel="noopener noreferrer">Learn More</a>'=>'Dërgoni email- në mënyrë jo sinkrone, çka do të bëjë që faqet me kërkesa email- të ngarkohen më shpejt, por mund të vonohet dërgimi i email-eve me një a dy minuta. <a href="%1$s" target="_blank" rel="noopener noreferrer">Mësoni Më Tepër</a>','Optimize Email Sending'=>'Optimizoni Dërgim Email-esh','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it seems they are missing. Please try to <a href="%1$s">create the missing DB tables by clicking on this link</a>. If this issue persists, please <a href="%2$s" target="_blank" rel="noopener noreferrer">contact our support</a>.'=>'WP Mail SMTP po përdor tabela të përshtatura baze të dhënash, për disa nga veçoritë e saj. Që të mund të funksionojnë si duhet, tabelat e përshtatura duhen krijuar dhe duket se mungojnë. Ju lutemi, provoni të <a href="%1$s">krijoni tabelat BD që mungojnë, duke klikuar mbi këtë lidhje</a>. Nëse problemi vazhdon, ju lutemi, <a href="%2$s" target="_blank" rel="noopener noreferrer">lidhuni me asistencën tonë</a>.','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it seems they are missing. Please try to <a href="%1$s">create the missing DB tables by clicking on this link</a>. If this issue persists, please <a href="%2$s" target="_blank" rel="noopener noreferrer">contact our support</a> and provide the error message below:'=>'WP Mail SMTP po përdor tabela të përshtatura baze të dhënash, për disa nga veçoritë e saj. Që të mund të funksionojnë si duhet, tabelat e përshtatura duhen krijuar dhe duket se mungojnë. Ju lutemi, provoni të <a href="%1$s">krijoni tabelat BD që mungojnë, duke klikuar mbi këtë lidhje</a>. Nëse problemi vazhdon, ju lutemi, <a href="%2$s" target="_blank" rel="noopener noreferrer">lidhuni me asistencën tonë</a> dhe jepni mesazhin e gabimit më poshtë:','We\'re sorry, Email Rate Limiting is not available on your plan. Please upgrade to the Pro plan to unlock all these awesome features.'=>'Na vjen keq, Kufizimi i Dërgimit të Email-eve s’është pjesë e planit tuaj. Ju lutemi, përmirësojeni me planin Pro, që të shkyçni krejt këto veçori mahnitëse.','Email Rate Limiting <br> is a Pro Feature'=>'Kufizim Dërgimi Email-esh <br> është një veçori Pro','Install the WPForms plugin and create beautiful contact forms with just a few clicks.'=>'Instaloni shtojcën WPForms dhe krijoni formularë të hijshëm kontakti vetëm me pak klikime.','Our Gmail mailer works with any Gmail or Google Workspace account via the Google API. You can send WordPress emails from your main email address or a Gmail alias, and it\'s more secure than connecting to Gmail using SMTP credentials. We now have a One-Click Setup, which simply asks you to authorize your Google account to use our app and takes care of everything for you. Alternatively, you can connect manually, which involves several steps that are more technical than other mailer options, so we created a detailed guide to walk you through the process.<br><br>To get started, read our <a href="%s" target="_blank" rel="noopener noreferrer">Gmail documentation</a>.'=>'Postuesi ynë Gmail funksionon me çfarëdo llogarie Gmail apo Google Workspace, përmes API-t Google. Mund të dërgoni email-e WordPress që nga adresa juaj kryesore email, ose nga një alias Gmail dhe është më e siguruar se sa lidhja me Gmail duke përdorur kredenciale SMTP. Tanimë kemi një Ujdisje Me Një Klikim, e cila thjesht ju kërkon të autorizoni llogarinë tuaj Google të përdorë aplikacionin tonë dhe kujdeset për gjithçka në vend se ju. Ndryshe, mund ta bëni lidhjen dorazi, çka përfshin disa hapa që janë më tepër teknikë se sa mundësitë e tjera për postuesin, ndaj krijuam një udhërrëfyes të hollësishëm për t’ju kaluar nëpër proces.<br><br>Për t’ia filluar, lexoni <a href="%s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për Gmail</a>.','We\'re sorry, One-Click Setup for Google Mailer is not available on your plan. Please upgrade to the Pro plan to unlock all these awesome features.'=>'Na vjen keq, Ujdisja Me Një Klikim për Google Mailer s’është pjesë e planit tuaj. Ju lutemi, përmirësojeni me planin Pro, që të shkyçni krejt këto veçori mahnitëse.','One-Click Setup for Google Mailer <br> is a Pro Feature'=>'Ujdisja Me Një Klikim për Google Mailer <br> është një veçori Pro','The email address that emails are sent from. You can use only the connected email address or its alias.'=>'Adresa email nga e cila dërgohen email-et. Mund të përdorni vetëm adresën e lidhur email, ose aliaset e saj.','The email address that emails are sent from. The email address that emails are sent from. You can use only the connected email address or its alias.'=>'Adresa email nga e cila dërgohen email-et. Mund të përdorni vetëm adresën e lidhur email, ose aliasin e saj.','The email address that emails are sent from. You can use only connected email address or his alias.'=>'Adresa email nga e cila dërgohen email-et. Mund të përdorni vetëm adresën e lidhur email, ose aliasin për të.','The email address that emails are sent from. You can use only connected email address or '=>'Adresa email nga e cila dërgohen email-et. Mund të përdorni vetëm adresën e lidhur email, ose ','You have successfully connected your site with your Gmail account. Now you can start sending emails through Gmail.'=>'E lidhët me sukses sajtin tuaj me llogarinë tuaj Gmail. Tani mund të filloni të dërgoni email-e përmes Gmail-it.','You have successfully connected your site with your Gmail account. This site will now send emails via your Gmail account.'=>'E keni lidhur me sukses sajtin tuaj me llogarinë tuaj Gmail. Ky sajt tanimë do të dërgojë email-e përmes llogarisë tuaj Gmail.','One-Click Setup for Google Mailer requires an active license. Verify your license to proceed with this One-Click Setup, please.'=>'Ujdisja Me Një Klikim për Google Mailer lyp një licencë aktive. Ju lutemi, që të vazhdohet me këtë Ujdisje Me Një Klikim, verifikoni licencën tuaj.','One-Click Setup for Google Mailer requires an active license. Verify your license to proceed with this one-click setup, please.'=>'Ujdisja Me Një Klikim për Google Mailer lyp një licencë aktive. Ju lutemi, që të vazhdohet me këtë ujdisje me një klikim, verifikoni licencën tuaj.','One-Click Setup for Google Mailer requires an active license. Verify your license to proceed with this one-click setup.'=>'Ujdisja Me Një Klikim për Google Mailer lyp një licencë aktive. Që të vazhdohet me këtë ujdisje me një klikim, verifikoni licencën tuaj.','One-Click Setup for Google Mailer requires an active license. Emails are currently not being sent.'=>'Ujdisja Me Një Klikim për Google Mailer lyp një licencë aktive. Aktualisht email-et nuk dërgohen.','Gmail mailer requires a valid Easy WP SMTP Pro license. Please activate your license key.'=>'Postuesi Gmail lyp një licencë Easy WP SMTP Pro të vlefshme. Ju lutemi, aktivizoni kyçin tuaj të licencës.','Now you can continue mailer configuration.'=>'Tani mund të vazhdoni formësimin e postuesve.','There was an error while processing the authentication request.'=>'Pati një gabim teksa përpunohej kërkesa për mirëfilltësim.','Sign in with Google'=>'Hyni me Google','Disabled'=>'E çaktivizuar','Enabled'=>'E aktivizuar','Provides a quick and easy way to connect to Google that doesn\'t require creating your own app.'=>'Jep një rrugë të shpejtë dhe të kollajtë për t’u lidhur me Google, e cila s’lyp krijimin e një aplikacioni tuajin.','One-Click Setup'=>'Ujdisje Me Një Klikim','Send emails from different additional connections based on your configured conditions. Emails that do not match any of the conditions below will be sent via your Primary Connection.'=>'Dërgoni email-e nga lidhje të ndryshme shtesë, bazuar në kushte formësuar nga ju. Email-et që s’kanë përputhje me asnjë nga kushtet më poshtë, do të dërgohen përmes Lidhjes suaj Parësore.','Configure SendLayer, SMTP.com or Brevo service'=>'Formësoni shërbimin SendLayer, SMTP.com ose Brevo','Install & Setup WP Mail SMTP Pro plugin'=>'Instaloni & Ujdisni shtojcën WP Mail SMTP Pro','Zoho Mail - use your Zoho Mail account to send emails'=>'Zoho Mail - përdorni llogarinë tuaj Zoho Mail për dërgim email-esh','Outlook - send emails using your Outlook or Microsoft 365 account'=>'Outlook - dërgoni email-e duke përdorur llogarinë tuaj Outlook ose Microsoft 365','Smart Routing - define conditions for your email sending'=>'Rrugëzim i Mençur - përkufizoni kushte për dërgimin e email-eve tuaj','Backup Connection - send emails even if your primary connection fails'=>'Lidhje Kopjeruajtje - dërgoni email-e edhe kur lidhja juaj parësore dështon','Alerts - get notified when your emails fail (via email, slack or SMS)'=>'Sinjalizime - njoftohuni kur dështojnë email-e (përmes email-i, Slack ose SMS)','All settings will be unrecoverable.'=>'Krejt rregullimet do të jenë të parikthyeshme.','Remove ALL WP Mail SMTP data upon plugin deletion.'=>'Hiqi KREJT të dhënat WP Mail SMTP, gjatë fshirjes së shtojcës.','Miscellaneous'=>'Të ndryshme','Email logging makes it easy to save details about all of the emails sent from your WordPress site. You can search and filter the email log to find specific messages and check the color-coded delivery status. Email logging also allows you to resend emails, save attachments, and export your logs in different formats.'=>'Regjistrimi i email-eve e bën të lehtë të ruhen hollësi mbi krejt email-et e dërguar që prej sajtit tuaj WordPress. Mundë të bëni kërkime te regjistri i email-eve dhe ta filtroni për të gjetur mesazhe specifike dhe të kontrolloni gjendjen e shkallës së dërgimit sipas kodesh me ngjyra. Regjistrimi i email-eve ju lejon gjithashtu të ridërgoni email-e, të ruani bashkëngjitje dhe të eksportoni regjistrat tuaj në formate të ndryshëm.','Easily export your logs to CSV or Excel. Filter the logs before you export and only download the data you need. This feature lets you easily create your own deliverability reports. You can also use the data in 3rd party dashboards to track deliverability along with your other website statistics.'=>'Eksportoni kollaj regjistrat tuaja si CSV ose Excel. Filtrojini regjistrat përpara eksportimit dhe shkarkoni vetëm të dhënat që ju duhen. Kjo veçori ju lejon të krijoni me lehtësi raportet tuaja mbi shkallën e dërgimit. Mundeni edhe të përdorni të dhëna në pulte nga palë të treta, për të ndjekur shkallën e dërgimit tok me statistika tuajat të tjera të sajtit.','Email reports make it easy to track deliverability and engagement at-a-glance. Your open and click-through rates are grouped by subject line, making it easy to review the performance of campaigns or notifications. The report also displays Sent and Failed emails each week so you spot any issues quickly. When you upgrade, we\'ll also add an email report chart right in your WordPress dashboard.'=>'Raportet mbi email-e e bëjnë të lehtë ndjekjen me një vështrim të shkallës së dërgimit dhe angazhimit. Vlerat për hapje dhe klikime në email-et tuaj grupohen sipas rreshtash subjekti, duke e bërë të lehtë shqyrtimin e suksesit të fushatave apo njoftimeve. Raporti shfaq gjithashtu email-e të Dërguar dhe të Dështuar për çdo javë, kështu që mund të vini re shpejt çfarëdo problemi. Kur e përmirësoni, do të shtojmë edhe një grafik raportesh email-esh mu te pulti i WordPress-it tuaj.','Email controls allow you to manage the automatic notifications you receive from your WordPress website. With the flick of a switch, you can reduce inbox clutter and focus on the alerts that matter the most. It\'s easy to disable emails about comments, email or password changes, WordPress updates, user registrations, and personal data requests.'=>'Kontrollet e email-it ju lejojnë të administroni njoftimet e automatizuara që merrni nga sajti juaj WordPress. Me lëvizjen e një çelësi mund të reduktoni rrëmujën te email-et që merrni dhe të përqendroheni te sinjalizimet që kanë më shumë vlerë. Është e lehtë të çaktivizohen email-e mbi komente, mbi ndryshime email-esh ose fjalëkalimesh, mbi përditësime të WordPress-it, regjistrime përdoruesish dhe kërkesa për të dhëna personale.','Get notified about emails that were successfully sent, but have hard bounced on delivery attempt. A hard bounce is an email that has failed to deliver for permanent reasons, such as the recipient\'s email address being invalid.'=>'Njoftohuni për email-e që dërguan me sukses, por për të cilët pati <em>hard bounce</em> gjatë përpjekjes për t’i livruar. Një <em>hard bounce</em> është një email që s’arriti të livrohej për arsye permanente, fjala vjen, adresa email e marrësit është e pavlefshme.','The deliverability verification process detects a hard bounce'=>'Procesi i verifikimit të livrimit pikas një <em>hard bounce</em>','This option is always enabled and will notify you about instant email sending failures.'=>'Kjo mundësi është përherë e aktivizuar dhe do t’ju njoftojë për dështime të atypëratyshme dërgimi email-esh.','The initial email sending request fails'=>'Kërkesa fillestare për dërgim email-i dështon','Notify when'=>'Njofto kur','Configure at least one of these integrations to receive notifications when email fails to send from your site. Alert notifications will contain the following important data: email subject, email Send To address, the error message, and helpful links to help you fix the issue.'=>'Formësoni të paktën një nga këto integrime, për të marrë njoftime gjatë rasteve kur dërgimi i email-eve nga sajti juaj dështon. Njoftimet sinjalizuese do të përmbajnë të dhënat e rëndësishme vijuese: subjekt email-i, adresën email “Dërgoje Për”, mesazhin e gabimit dhe lidhje të dobishme për t’ju ndihmuar të ndreqni problemin.','Create additional connections to set a backup for your Primary Connection or to configure Smart Routing.'=>'Krijoni lidhje shtesë për të ujdisur një kopjeruajtje për Lidhjen tuaj Parësore, ose për të formësuar Rrugëzim të Mençur.','Free Plugins'=>'Shtojca Falas','Support'=>'Asistencë','Made with ♥ by the WP Mail SMTP team'=>'Krijuar me ♥ nga ekipi i WP Mail SMTP PRO','Improve your SEO rankings with the All in One SEO plugin.'=>'Përmirësoni renditjen tuaj SEO me shtojcën “All in One SEO”.','Follow this link to <a href="%s" target="_blank" rel="noopener noreferrer">get a Mailgun API Key</a>. Generate a key in the "Mailgun API Keys" section.'=>'Ndiqni këtë lidhje që të <a href="%s" target="_blank" rel="noopener noreferrer">merrni një Kyç API për Mailgun</a>. Prodhoni një kyç te pjesa “Mailgun API Keys”.','The following DB table is still missing.'=>'Tabela vijues Baze të Dhënash ende mungon.' . "\0" . 'Tabelat vijuese Baze të Dhënash ende mungojnë.','Code Snippets by WPCode'=>'Copëza kodi nga WPCode','Triple-check the plugin settings and consider reconfiguring to make sure everything is correct. Maybe there was an issue with copy&pasting.'=>'Kontrolloni dhe rikontrolloni edhe një herë rregullimet e shtojcës dhe shihni mundësinë e riformësimit, për të siguruar që gjithçka është saktë. Mbase pati një problem me kopjim&ngjitje.','Make sure you are not sending emails with too many recipients. Example: single email should not have 10+ recipients. You can install any WordPress e-mail logging plugin to check your recipients (TO, CC and BCC).'=>'Sigurohuni se nuk po dërgoni email-e me shumë marrës. Shembull: një email njësh s’duhet të ketë 10 marrës e ca. Mundeni të instaloni çfarëdo shtojce WordPress për regjistrim veprimtarie email-i që të kontrolloni marrësit tuaj (PËR, CC dhe BCC).','Dismiss email alert block'=>'Bllok “Hidhe tej sinjalizimin me email”','<a href="%s" target="_blank" rel="noopener noreferrer">Upgrade to Pro</a> and get instant alert notifications when they fail.'=>'<a href="%s" target="_blank" rel="noopener noreferrer">Përmirësojeni me versionin Pro</a> dhe merrni njoftime të atypëratyshme sinjalizuese, kur dështojnë.','We detected %d failed email in the last 30 days.'=>'Pikasëm %d email të dështuar në 30 ditët e fundit.' . "\0" . 'Pikasëm %d emaile të dështuar në 30 ditët e fundit.','Error icon'=>'Ikonë gabimi','The Email Test tab was moved to <a href="%s">WP Mail SMTP > Tools</a>.'=>'Skeda e Email-it të Provës u kalua te <a href="%s">WP Mail SMTP > Mjete</a>.','%1$sFollow this link%2$s to get a Mailgun API Key. Generate a key in the "Mailgun API Keys" section.'=>'%1$sNdiqni këtë lidhje%2$s që të merrni një Kyç API për Mailgun. Prodhoni një kyç te pjesa “Mailgun API Keys”.','Mailgun API Key'=>'Kyç API për Mailgun','The following plugin will be installed for free:'=>'Shtojca vijuese do të instalohet falas:','Improve your website\'s SEO ranking with our toolkit.'=>'Përmirësoni renditjen SEO të sajtit tuaj, me grupin tonë të mjeteve.','WordPress SEO Toolkit'=>'Grup mjetesh SEO për WordPress','Brevo'=>'Brevo','Get Brevo Now (Free)'=>'Merreni Brevo-n Që Tani (Falas)','We believe in full transparency. The Brevo (formerly Sendinblue) links above are tracking links as part of our partnership with Brevo. We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Besojmë në transparencën e plotë. Lidhjet Brevo (ish-Sendinblue) më sipër janë lidhje gjurmimi, si pjesë e bashkëpunimit tonë me Brevo-n. Mund të rekomandojmë thuajse cilindo shërbim SMTP, por mund të rekomandojmë vetëm produkte që besojmë se do të shtojnë vlerë për përdoruesit tanë.','We believe in full transparency. The Brevo links above are tracking links as part of our partnership with Brevo. We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Besojmë në transparencën e plotë. Lidhjet Brevo më sipër janë lidhje gjurmimi, si pjesë e bashkëpunimit tonë me Brevo-n. Mund të rekomandojmë thuajse cilindo shërbim SMTP, por mund të rekomandojmë vetëm produkte që besojmë se do të shtojnë vlerë për përdoruesit tanë.','Read how to set up Brevo'=>'Lexoni si të ujdiset Brevo-ja','Get Started with Brevo'=>'Fillojani me Brevo-n','Please input the sending domain/subdomain you configured in your Brevo dashboard. More information can be found in our %1$sBrevo documentation%2$s'=>'Ju lutemi, jepni përkatësinë/nënpërkatësinë e dërgimit që formësuat te pulti juaj në Brevo. Më tepër të dhëna mund të gjenden te  %1$sdokumentimi ynë për Brevo%2$s','Duplicator Pro'=>'Duplicator Pro','Leading WordPress backup & site migration plugin. Over 1,500,000+ smart website owners use Duplicator to make reliable and secure WordPress backups to protect their websites. It also makes website migration really easy.'=>'Shtojca kryesuese WordPress për kopjeruajtje & migrim sajtesh. Mbi 1 milion e gjysmë të zotë të mençur sajtesh e përdorin Duplicator-in për të bërë kopjeruajtje të besueshme dhe të siguruara WordPress për të mbrojtur sajtet e veta. Veç të tjerash e bën migrimin e sajteve vërtet të lehtë.','Duplicator'=>'Duplicator','WPCode Pro'=>'WPCode Pro','Future proof your WordPress customizations with the most popular code snippet management plugin for WordPress. Trusted by over 1,500,000+ websites for easily adding code to WordPress right from the admin area.'=>'Bëjini të paprekshme nga e ardhmja përshtatjet tuaja të WordPress-it, me shtojcën më popullore për administrim copëzash kodi për WordPress. E besuar nga mbi 1 milion e gjysmë sajte për shtim të kollajtë kodi në WordPress, drejt e nga zona e përgjegjësit.','WPCode Lite'=>'WPCode Lite','Top-rated WordPress donation and fundraising plugin. Over 10,000+ non-profit organizations and website owners use Charitable to create fundraising campaigns and raise more money online.'=>'Shtojcë WordPress për dhurime dhe mbledhje fondesh, e vlerësuar me maksimumin. Mbi 10 mijë të zotë entesh jofitimprurës dhe sajtesh e përdorin Charitable për të krijuar fushata mbledhjeje fondesh dhe për të mbledhur më tepër para në internet.','We\'re sorry, the %name% mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Na ndjeni, postuesi %name% s’është pjesë e planit tuaj. Ju lutemi, përmirësojeni me planin PRO që të çlirohen krejt këto veçori të mahnitshme.','WP Core (%s)'=>'Bazë e WP-it (%s)','Primary'=>'Parësore','Friendly reminder, your Primary Connection will be used for all emails that do not match the conditions above.'=>'Sa për t’jua kujtuar miqësisht, Lidhja juaj Parësore do të përdoret për krejt email-et që nuk kanë përputhje me kushtet më sipër.','Light bulb icon'=>'Ikonë llambe','Initiator'=>'Initiator','Contact Emails (SMTP.com)'=>'Email-e Kontakti (SMTP.com)','Add New Group'=>'Shtoni Grup të Ri','or'=>'ose','Is'=>'Është','And'=>'Dhe','Order'=>'Rend','Contains'=>'Përmban','Arrow Down'=>'Shigjetë Për Poshtë','Arrow Up'=>'Shigjetë Për Sipër','if the following conditions are met...'=>'nëse kushtet vijuese janë plotësuar…','WooCommerce Emails (SendLayer)'=>'Email-e WooCommerce (SendLayer)','Send with'=>'Dërgoje me','Enable Smart Routing'=>'Aktivizo Rrugëzim të Mençur','Once you add an <a href="%s">additional connection</a>, you can select it here.'=>'Pasi të shtoni një <a href="%s">lidhje shtesë</a>, mund ta përzgjidhni këtu.','Don’t worry about losing emails. Add an additional connection, then set it as your Backup Connection. Emails that fail to send with the Primary Connection will be sent via the selected Backup Connection. <a href="%s" target="_blank" rel="noopener noreferrer">Upgrade to WP Mail SMTP Pro!</a>'=>'Mos u shqetësoni për humbje email-esh. Shtoni një lidhje shtesë, mandej vëreni si Lidhjen tuaj Rrugëdalje. Email-et që nuk arrihen të dërgohen përmes Lidhjes Parsore, do të dërgohen përmes Lidhjes Rrugëdalje të përzgjedhur. <a href="%s" target="_blank" rel="noopener noreferrer">Përmirësojeni me WP Mail SMTP Pro!</a>','Primary Connection'=>'Lidhje Parësore','Create advanced routing rules'=>'Krijoni rregulla të mëtejshëm rrugëzimi','Use mailers for different purposes'=>'Përdorni postues për qëllime të ndryshme','Set a Backup Connection'=>'Ujdisni një Lidhje Rrugëdalje','With additional connections you can...'=>'Me lidhje shtesë mund të…','Smart Routing'=>'Rrugëzim i Mençur','Backup Connection'=>'Lidhje Rrugëdalje','Additional Connections'=>'Lidhje Shtesë','There was an error while processing the authentication request. The state key is invalid. Please try again.'=>'Pati një gabim teksa kryhej kërkesa e mirëfilltësimit. Kyçi i gjendjes është i pavlefshëm. Ju lutemi, riprovoni.','Remove OAuth Connection'=>'Hiq Lidhje oAuth','It looks like we can\'t remove OAuth connection.'=>'Duket sikur s’heqim dot lidhje oAuth.','create the missing DB tables by clicking on this link'=>'krijoni tabelat e Bazës së të Dhënave që mungojnë, duke klikuar mbi këtë lidhje','Go to WP Mail SMTP settings page.'=>'Kaloni te faqja e rregullimeve për WP Mail SMTP.','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it seems they are missing. Please try to <a href="%1$s" target="_self" aria-label="%2$s" rel="noopener noreferrer">%3$s</a>. If this issue persists, please contact our support.'=>'Për disa nga veçoritë e veta, WP Mail SMTP po përdor tabela të përshtatura baze të dhënash. Që të funksionojnë si duhet, tabelat e përshtatura duhen krijuar, por duket se mungojnë. Ju lutemi, provoni <a href="%1$s" target="_self" aria-label="%2$s" rel="noopener noreferrer">%3$s</a>. Nëse ky problem vazhdon, lidhuni me asistencën tonë.','Some DB Tables are still missing.'=>'Disa Tabela Baze të Dhënash ende mungojnë.','Missing DB tables were created successfully.'=>'Tabelat e bazës së të dhënave që mungonin u krijuan me sukses.','<strong>Table:</strong> %1$s. <strong>Reason:</strong> %2$s'=>'<strong>Tabelë:</strong> %1$s. <strong>Arsye:</strong> %2$s','Unknown.'=>'E panjohur.','%d Day'=>'%d Ditë' . "\0" . '%d Ditë','1 Year'=>'1 Vit','6 Months'=>'6 Muaj','3 Months'=>'3 Muaj','1 Month'=>'1 Muaj','1 Week'=>'1 Javë','Debug events older than the selected period will be permanently deleted from the database.'=>'Veprimtari diagnostikimi më të vjetra se periudha e përzgjedhur do të fshihen përgjithmonë nga baza e të dhënave.','Forever'=>'Përgjithmonë','Events Retention Period'=>'Periudhë Mbajtjeje Veprimtarish','[%1$d] %2$s called at [%3$s:%4$s]'=>'[%1$d] %2$s thirrur te [%3$s:%4$s]','Track when a link in an email is clicked'=>'Ndiqni se kur klikohet një lidhje në një email','Complete Email Reports'=>'Raporte të Plotë Email-esh','See the delivery status, track opens and clicks, and create deliverability graphs.'=>'Shihni gjendje dërgimi, ndiqni hapje dhe klikime dhe krijoni grafikë shkalle dërgimi.','Get notifications via email, SMS, Slack, or webhook when emails fail to send.'=>'Merrni njoftime përmes email-i, SMS-je, Slack-u, apo webhook-ësh, kur s’arrijnë të dërgohen email-e.','Instant Email Alerts'=>'Sinjalizime të Atypëratyshme Email-esh','This option must be enabled if you\'d like to be able to resend emails. Please be aware that all email content will be stored in your WordPress database. This may include sensitive data, passwords, and personal details.'=>'Kjo mundësi duhet aktivizuar, nëse do të donit të jeni në gjendje të ridërgoni email-e. Ju lutemi, kini parasysh se krejt lënda e email-eve do të depozitohet në bazën e të dhënave të WordPress-it tuaj. Këtu mund të përfshihen të dhëna rezervat, fjalëkalime dhe hollësi personale.','Enable these powerful logging features for more control of your WordPress emails.'=>'Aktivizojini këto veçori të fuqishme regjistrimi, për më tepër kontroll të email-eve tuaj WordPress.','See which links were clicked in emails sent from your WordPress site. Click tracking works with emails that are sent in HTML format.'=>'Shihni cilat lidhje qenë klikuar në email-e të dërguar që nga sajti juaj WordPress. Ndjekja e klikimeve funksionon me email-e që janë dërguar në formatin HTML.','See which emails were opened by the recipients. Email open tracking works with emails that are sent in HTML format.'=>'Shihni cilët email-e qenë hapur nga marrësti. Ndjekja e hapjes së email-eve funksionon me email-e që janë dërguar në formatin HTML.','Track when an email is opened'=>'Ndiqni se kur hapet një email','All file attachments sent from your site will be saved to the WordPress Uploads folder. Please note that this may reduce available disk space on your server.'=>'Krejt kartelat bashkëngjitje dërguar nga sajti juaj do të ruhen te dosja Ngarkime e WordPress-it. Ju lutemi, mbani parasysh se kjo mund të zvogëlojë sasinë e hapësirës së lirë në shërbyesin tuaj.','Save file attachments sent from WordPress'=>'Ruaji kartelat bashkëngjitje dërguar që nga WordPress-i','Store the content for all sent emails'=>'Depozito lëndën për krejt email-et e dërguar','Configure Email Logs'=>'Formësoni Regjistra Email-esh','%1$sFollow this link%2$s to get a Private API Key from Mailgun.'=>'Që të merrni një Kyç Privat APi prej Mailgun-it, %1$sndiqni këtë lidhje%2$s.','Let’s see how many emails you’ve sent with WP Mail SMTP.'=>'Le të shohim sa email-e keni dërguar me WP Mail SMTP.','Current function path: %s'=>'Shteg i tanishëm funksioni: %s','It looks like it\'s overwritten in the "wp-config.php" file. Please reach out to your hosting provider on how to disable or remove the "wp_mail" function overwrite to prevent conflicts with WP Mail SMTP.'=>'Duket sikur është mbishkruar te kartela “wp-config.php”. Ju lutemi, se si të çaktivizoni apo hiqni mbishkrimin e funksionit “wp_mail”, që të parandalohen përplasje me WP Mail SMTP, lidhuni me shërbimin që strehon sajtin tuaj.','It looks like the "%s" must-use plugin is overwriting the "wp_mail" function. Please reach out to your hosting provider on how to disable or remove the "wp_mail" function overwrite to prevent conflicts with WP Mail SMTP.'=>'Duket sikur shtojca <em>must-use</em> “%s” mbishkruan funksionin “wp_mail”. Ju lutemi, se si të çaktivizoni apo hiqni mbishkrimin e funksionit “wp_mail”, që të parandalohen përplasje me WP Mail SMTP, lidhuni me shërbimin që strehon sajtin tuaj.','It looks like the "%s" plugin is overwriting the "wp_mail" function. Please reach out to the plugin developer on how to disable or remove the "wp_mail" function overwrite to prevent conflicts with WP Mail SMTP.'=>'Duket sikur shtojca “%s” mbishkruan funksionin “wp_mail”. Ju lutemi, se si të çaktivizoni apo hiqni mbishkrimin e funksionit “wp_mail”, që të parandalohen përplasje me WP Mail SMTP, lidhuni me shërbimin që strehon sajtin tuaj.','WP Mail SMTP has detected incorrect "wp_mail" function location. Usually, this means that emails will not be sent successfully!'=>'WP Mail SMTP ka pikasur vendndodhje të pasaktë të funksionit “wp_mail”. Zakonisht, kjo do të thotë se email-et tuaj s’do të dërgohen me sukses!','Or deactivate "SMTP" module in Branda > Emails > SMTP.'=>'Ose çaktivizoni modulin “SMTP”, te Branda > Emails > SMTP.','Webhook Alerts'=>'Sinjalizime Webhook','Paste in the webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up webhook alerts.'=>'Hidhni këtu URL-në e webhook-ut që do të donit të përdoret për të marrë sinjalizime, kur dërgimi i email-eve dështon. Se si të ujdisjen sinjalizime për <em>webhook</em>, lexoni dokumentimin tonë.','Webhook'=>'Webhook','To Phone Number'=>'Për Numër Telefoni','From Phone Number'=>'Nga Numër Telefoni','Twilio Auth Token'=>'Token Mirëfilltësimi Twilio','Twilio Account ID'=>'ID Llogarie Twilio','SMS via Twilio Alerts'=>'SMS përmes Twilio Alerts','To receive SMS alerts, you’ll need a Twilio account. Read our documentation to learn how to set up Twilio SMS, then enter your connection details below.'=>'Që të merrni sinjalizime me SMS, do t’ju duhet një llogari Twilio. Për të mësuar se si të ujdisni Twilio SMS, lexoni dokumentimin tonë, mandej jepni më poshtë hollësitë e lidhjes tuaj.','SMS via Twilio'=>'SMS përmes Twilio','Webhook URL'=>'URL webhook-u','Slack Alerts'=>'Sinjalizime Slack','Paste in the Slack webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up Slack alerts.'=>'Hidhni këtu URL-në e webhook-ut Slack që do të donit të përdoret për të marrë sinjalizime, kur dërgimi i email-eve dështon. Se si të ujdisjen sinjalizime për Slack, lexoni dokumentimin tonë.','Slack'=>'Slack','Email Alerts'=>'Sinjalizime Me Email','Enter the email addresses (3 max) you’d like to use to receive alerts when email sending fails. Read our documentation on setting up email alerts.'=>'Jepni adresat email (3 e shumta) që do të donit të marrin sinjalizime, kur dërgimi i email-it dështon. Për ujdisje sinjalizimesh email-i, lexoni dokumentimin tonë.','Alerts'=>'Sinjalizime','There was an error while processing the authentication request. The authorization code is missing. Please try again.'=>'Pati një gabim teksa përpunohej kërkesa e mirëfilltësimit. Mungon kodi i autorizimit. Ju lutemi, riprovoni.','There was an error while processing the authentication request. The nonce is invalid. Please try again.'=>'Pati një gabim teksa kryhej kërkesa e mirëfilltësimit. Nonce-i është i pavlefshëm. Ju lutemi, riprovoni.','Follow this link to get an API Key from SendLayer: %s.'=>'Ndiqni këtë lidhje që të merrni një Kyç API prej SendLayer-i: %s.','SendLayer'=>'SendLayer','<strong><a href="%1$s" target="_blank" rel="noopener noreferrer">SendLayer</a> is our #1 recommended mailer.</strong> Its affordable pricing and simple setup make it the perfect choice for WordPress sites. SendLayer will authenticate your outgoing emails to make sure they always hit customers’ inboxes, and it has detailed documentation to help you authorize your domain.<br><br>You can send hundreds of emails for free when you sign up for a trial.<br><br>To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">SendLayer documentation</a>.'=>'<strong><a href="%1$s" target="_blank" rel="noopener noreferrer">SendLayer</a> është postuesi #1 i rekomanduar prej nesh.</strong> Çmimet e arritshme dhe ujdisja e thjeshtë e bëjnë zgjedhjen e përkryer për sajte WordPress. SendLayer-i do të kryejë mirëfilltësimin e email-eve të dërguar prej jush, për të garantuar se mbërrijnë përherë në kutitë postare të klientëve dhe ka dokumentim të hollësishëm për t’ju ndihmuar të autorizoni përkatësinë tuaj.<br><br>Mund të dërgoni qindra email-e falas, kur regjistroheni për ta provuar.<br><br>Që t’ia filloni, lexoni <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentimin tonë mbi SendLayer-in</a>.','Verify your domain Region is correct.'=>'Verifikoni që Rajoni i përkatësisë tuaj të jetë i saktë.','Verify your <a href="%1$s" target="_blank" rel="noopener noreferrer">Domain Name</a> is correct.'=>'Verifikoni se <a href="%1$s" target="_blank" rel="noopener noreferrer">Emri i Përkatësisë tuaj</a> është i saktë.','Go to your Mailgun account and verify that your <a href="%1$s" target="_blank" rel="noopener noreferrer">Mailgun API Key</a> is correct.'=>'Kaloni te llogaria juaj Mailgun dhe verifikoni se <a href="%1$s" target="_blank" rel="noopener noreferrer">Kyçi juaj API për Mailgun-n</a> është i saktë.','Typically this error occurs because there is an issue with your Mailgun settings, in many cases Mailgun API Key, Domain Name, or Region is incorrect.'=>'Zakonisht ky gabim ndodh ngaqë ka një problem me rregullimet tuaja për Mailgun-in, në mjaft raste Kyçi për API-n Mailgun, Emri i Përkatësisë, ose Rajoni është i pasaktë.','Docs'=>'Dokumentime','Go to WPMailSMTP.com documentation page'=>'Kaloni te faqja e dokumentimit të WPMailSMTP.com','Get WP Mail SMTP Pro'=>'Merrni WP Mail SMTP Pro','Get Started with SendLayer'=>'Si T’ia Fillohet me SendLayer-in','Read how to set up SendLayer'=>'Lexoni se si të ujdiset SendLayer-i','%1$sFollow this link%2$s to get an API Key for SendLayer.'=>'Që të merrni një Kyç API për SendLayer-in, %1$sndiqni këtë lidhje%2$s.','Read how to set up SendGrid'=>'Lexoni si të ujdiset SendGrid-i','<strong>WP Mail SMTP plugin is disabled</strong> on your site until WordPress is updated to the required version.'=>'<strong>Shtojca WP Mail SMTP është e çaktivizuar</strong> në sajtin tuaj, derisa të përditësohet WordPress-i me versionin e nevojshëm.','Your site is running an <strong>old version</strong> of WordPress that is no longer supported by WP Mail SMTP. Please update your WordPress site to at least version <strong>%s</strong>.'=>'Sajti juaj po xhiron një <strong>version të vjetër</strong> të WordPress-ir, që nuk mbulohet më nga WP Mail SMTP. Ju lutemi, përditësojeni sajtin tuaj WordPress me të paktën versionin <strong>%s</strong>.','Debug Output:'=>'<em>Output</em> Diagnostikimi:','If you create a test email on this page, it will still be sent.'=>'Nëse krijoni një email test në këtë faqe, prapë do të dërgohet.','Or enable "Do not change email sender by default" setting in Settings > Email template > Sender (tab).'=>'Ose aktivizoni “Si parazgjedhje, mos e ndrysho dërguesin e email-eve”, që nga Rregullime > Gjedhe email > Dërgues (skeda).','Could not install the plugin. You don\'t have permission to activate plugins.'=>'S’u instalua dot shtojca. S’keni leje të aktivizoni shtojca.','Visit <a href="%s" target="_blank" rel="noopener noreferrer">our documentation</a> for additional tips on how to resolve this error.'=>'Për ndihmëza shtesë se si të zgjidhet ky gabim, vizitoni <a href="%s" target="_blank" rel="noopener noreferrer">dokumentimin tonë</a>.','On this page, you can view different plugin debugging events and email sending errors.'=>'Në këtë faqe, mund të shihni akte të ndryshme diagnostikimi shtojce dhe gabime dërgimi email-i.','Could not install the plugin. Plugin is not whitelisted.'=>'S’u instalua dot shtojca. Shtojca s’gjendet në listën e të lejuarave.','Could not activate the plugin. Plugin is not whitelisted.'=>'S’u aktivizua dot shtojca. Shtojca s’gjendet në listën e të lejuarave.','Sugar Calendar'=>'Sugar Calendar','A simple & powerful event calendar plugin for WordPress that comes with all the event management features including payments, scheduling, timezones, ticketing, recurring events, and more.'=>'Një shtojcë WordPress-i e thjeshtë & e fuqishme për kalendar veprimtarish, që vjen me krejt veçoritë e administrimit të veprimtarive, përfshi pagesa, vënie në plan, zona kohore, sistem administrimi biletash, veprimtari me përsëritje, etj.','Sugar Calendar Lite'=>'Sugar Calendar Lite','The best WordPress eCommerce plugin for selling digital downloads. Start selling eBooks, software, music, digital art, and more within minutes. Accept payments, manage subscriptions, advanced access control, and more.'=>'Shtojca më e mirë WordPress për eCommerce për shitje shkarkimesh dixhitale. Filloni të shitni e-libra, <em>software</em>, muzikë, art dixhital, etj, brenda pak minutash. Pranoni pagesa, administroni pajtime, kontroll i thelluar hyrjesh, etj.','Easy Digital Downloads'=>'Easy Digital Downloads','WP Simple Pay Pro'=>'WP Simple Pay Pro','The #1 Stripe payments plugin for WordPress. Start accepting one-time and recurring payments on your WordPress site without setting up a shopping cart. No code required.'=>'Shtojca numër 1 për pagesa Stripe për WordPress-in. Filloni të pranoni pagesa një herë ose përsëritëse në sajtin tuaj WordPress pa ujdisur ndonjë shportë blerjesh. S’ka nevojë për programim.','WP Simple Pay'=>'WP Simple Pay','AffiliateWP'=>'AffiliateWP','The most advanced WordPress search plugin. Customize your WordPress search algorithm, reorder search results, track search metrics, and everything you need to leverage search to grow your business.'=>'Shtojca WordPress më e thelluar për kërkime. Përshtatni algoritmin tuaj të kërkimeve për WordPress, rirenditni përfundime kërkimesh, ndiqni matje kërkimi, gjithçka ju duhet për të shfrytëzuar kërkimin për shtimin e biznesit tuaj.','SearchWP'=>'SearchWP','Visit Site'=>'Vizitoni Sajtin','<a href="%s" rel="" target="_blank">More information</a> on SparkPost.'=>'<a href="%s" rel="" target="_blank">Më tepër të dhëna</a> mbi SparkPost.','Select your SparkPost account region.'=>'Përzgjidhni rajonin e llogarisë tuaj SparkPost.','Follow this link to get an API Key from SparkPost: %s.'=>'Ndiqni këtë lidhje që të merrni një Kyç API prej SparkPost-i: %s.','SparkPost'=>'SparkPost','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">SparkPost documentation</a>.'=>'Për t’ia filluar, lexoni <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për SparkPost-in</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost</a> is a transactional email provider that\'s trusted by big brands and small businesses. It sends more than 4 trillion emails each year and reports 99.9%% uptime. You can get started with the free test account that lets you send up to 500 emails per month.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost</a> është një shërbim transaksionesh email-esh i besuar nga marka të njohura dhe biznese të vogla. Dërgon më shumë se 4 trilion email-e çdo vit dhe njofton për 99.9%% kohë funksionimi shërbimi. Mund t’ia filloni me llogarinë provë falas që ju lejon të dërgoni deri në 500 email-e në muaj.','Region:'=>'Rajon:','API Key:'=>'Kyç API:','365 / Outlook'=>'365 / Outlook','Google / Gmail'=>'Google / Gmail','Verify that your SparkPost account region is selected in WP Mail SMTP settings.'=>'Verifikoni se rajoni i llogarisë tuaj SparkPost është i përzgjedhur te rregullimet e WP Mail SMTP-së.','Typically this error occurs because there is an issue with your SparkPost settings, in many cases an incorrect region.'=>'Zakonisht ky gabim ndodh ngaqë ka një problem me rregullimet tuaja për SparkPost-in, në mjaft raste një rajon i pasaktë.','Verify that your API key has "Transmissions: Read/Write" permission.'=>'Verifikoni se kyçi juaj API ka leje “Transmissions: Read/Write”.','Go to your <a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost account</a> or <a href="%2$s" target="_blank" rel="noopener noreferrer">SparkPost EU account</a> and verify that your API key is correct.'=>'Kaloni te <a href="%1$s" target="_blank" rel="noopener noreferrer">llogaria juaj SparkPost</a> ose <a href="%2$s" target="_blank" rel="noopener noreferrer">llogari SparkPost EU</a> dhe verifikoni se kyçi juaj për API-n është i saktë.','Typically this error occurs because there is an issue with your SparkPost settings, in many cases an incorrect API key.'=>'Zakonisht ky gabim ndodh ngaqë ka një problem me rregullimet tuaja për SparkPost-in, në mjaft raste një kyç API i pasaktë.','SparkPost API failed.'=>'API SparkPost dështoi.','Your mailer is already configured in a WP Mail SMTP constant, so the options below have been disabled. To change your mailer, please edit or remove the <code>WPMS_MAILER</code> constant in your <code>wp-config.php</code> file.'=>'Postuesi juaj është formësuar tashmë në një konstante të WP Mail SMTP-së, ndaj mundësia më poshtë është çaktivizuar. Që të ndryshoni postuesin tuaj, ju lutemi, përpunoni ose hiqni konstanten <code>WPMS_MAILER</code> te kartela juaj <code>wp-config.php</code>.','This setting is already configured with the WP Mail SMTP constant. To change it, please edit or remove the <code></code> constant in your <code>wp-config.php</code> file.'=>'Ky rregullim është formësuar tashmë te një konstante e WP Mail SMTP-së. Që ta ndryshoni, ju lutemi, përpunoni ose hiqni konstanten <code></code> te kartela juaj <code>wp-config.php</code>.','FluentSMTP'=>'FluentSMTP','Microsoft 365 / Outlook'=>'Microsoft 365 / Outlook','Select your SparkPost account region. %1$sMore information%2$s on SparkPost.'=>'Përzgjidhni rajonin e llogarisë tuaj SparkPost. %1$sMë tepër informacion%2$s mbi SparkPost-in.','Read how to set up SparkPost'=>'Lexoni si të ujdiset SparkPost-i','%1$sFollow this link%2$s to get an API Key for SparkPost.'=>'%1$sNdiqni këtë lidhje%2$s që të merrni një Kyç APi për SparkPost.','To get started, read our <a href="%s" target="_blank" rel="noopener noreferrer">SMTP.com documentation</a>.'=>'Për t’ia filluar, lexoni <a href="%s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për SMTP.com</a>.','<strong><a href="%s" target="_blank" rel="noopener noreferrer">SMTP.com</a> is one of our recommended mailers.</strong> It\'s a transactional email provider that\'s currently used by 100,000+ businesses. SMTP.com is an established brand that\'s been offering email services for more than 20 years.<br><br>SMTP.com offers a free 30-day trial that allows you to send up to 50,000 emails.'=>'<strong><a href="%s" target="_blank" rel="noopener noreferrer">SMTP.com</a> është një nga postuesit tanë të rekomanduar.</strong> Është një shërbim transaksionesh email-esh që aktualisht është në përdorim nga mbi 100 mijë biznese. SMTP.com është një markë e stabilizuar që ofron shërbime email për më shumë se 20 vjet.<br><br>SMTP.com ofron një provë për 30 ditë që ju lejon të dërgoni deri në 50 mijë email-e.','The Other SMTP option lets you send emails through an SMTP server instead of using a provider\'s API. This is easy and convenient, but it\'s less secure than the other mailers. Please note that your provider may not allow you to send a large number of emails. In that case, please use a different mailer.<br><br>To get started, read our <a href="%s" target="_blank" rel="noopener noreferrer">Other SMTP documentation</a>.'=>'Mundësia “Tjetër SMTP” ju lejon të dërgoni email-e përmes një shërbyesi SMTP, në vend se të përdoret një API shërbimi. Kjo është e lehtë dhe me leverdi, por është më pak e sigurt se sa postuesit e tjerë. Ju lutemi, kini parasysh se shërbimi juaj mund të mos ju lejojë të dërgoni një numër të madh email-esh. Në rast të tillë, ju lutemi, përdorni një tjetër postues.<br><br>Për t’ia filluar, lexoni <a href="%s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për “Tjetër SMTP”</a>.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Brevo documentation</a>.'=>'Për t’ia filluar, lexoni <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për Brevo</a>.','<strong><a href="%1$s" target="_blank" rel="noopener noreferrer">Brevo</a> (formerly Sendinblue) is one of our recommended mailers.</strong> It\'s a transactional email provider with scalable price plans, so it\'s suitable for any size of business.<br><br>If you\'re just starting out, you can use Brevo\'s free plan to send up to 300 emails a day. You don\'t need to use a credit card to try it out. When you\'re ready, you can upgrade to a higher plan to increase your sending limits.'=>'<strong><a href="%1$s" target="_blank" rel="noopener noreferrer">Brevo</a> (ish-Sendinblue) është një nga postuesit tanë të rekomanduar.</strong> Është një shërbim transaksionesh email-esh me plane çmimesh të përshkallëzueshme, ndaj është i përshtatshëm për çfarëdo madhësie biznesi.<br><br>Nëse jeni në fillimet, mund të përdorni planin falas të Brevo-s, për të dërguar deri në 300 email-e në ditë. S’ju duhet të përdorni kartë krediti për ta provuar,. Kur të jeni gati, mund ta përmirësoni me një plan më sipër, që të zmadhoni kufijtë tuaj për dërgime.','<a href="%1$s" target="_blank" rel="noopener noreferrer">SendGrid</a> is a popular transactional email provider that sends more than 35 billion emails every month. If you\'re just starting out, the free plan allows you to send up to 100 emails each day without entering your credit card details.<br><br>To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">SendGrid documentation</a>.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">SendGrid</a> është një shërbim popullor transaksionesh email-esh që dërgon më shumë se 35 miliardë email-e çdo muaj. Nëse jeni në fillimet, plani falas ju lejon të dërgoni deri në 100 email-e çdo ditë, pa dhënë hollësi të kartës tuaj të kreditit.<br><br>Për t’ia filluar, lexoni <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për SendGrid</a>.','Message Stream ID is <strong>optional</strong>. By default <strong>outbound</strong> (Default Transactional Stream) will be used. More information can be found in our <a href="%s" target="_blank" rel="noopener noreferrer">Postmark documentation</a>.'=>'ID Rrjedhe Mesazhesh është <strong>opsional</strong>. Si parazgjedhje, do të përdoret <strong>outbound</strong> (Rrjedhë Parazgjedhje Transaksionale). Më tepër hollësi mund të gjendet te <a href="%s" target="_blank" rel="noopener noreferrer">dokumentimi ynë për Postmark-un</a>.','Get Server API Token'=>'Merrni Token API Shërbyesi','Follow this link to get a Server API Token from Postmark: %s.'=>'Që të merrni një Token API Shërbyesi nga Postmark-u, ndiqni këtë lidhje: %s.','Postmark'=>'Postmark','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Postmark documentation</a>.'=>'Për t’ia filluar, lexoni <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për Postmark-un</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Postmark</a> is a transactional email provider that offers great deliverability and accessible pricing for any business. You can start out with the free trial that allows you to send 100 test emails each month via its secure API.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Postmark</a> është një shërbim popullor transaksionesh email-esh që ofron shkallë të shkëlqyer dërgimi dhe çmime të arritshme për çfarëdo biznesi. Mundeni t’ia filloni me provën falas, e cila ju lejon të dërgoni 100 email-e çdo muaj, përmes API-t të vet të sigurt.','Message Stream ID:'=>'ID Rrjedhe Mesazhesh:','Server API Token:'=>'Token API shërbyesi:','<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailgun</a> is a transactional email provider that offers a generous 3-month free trial. After that, it offers a \'Pay As You Grow\' plan that allows you to pay for what you use without committing to a fixed monthly rate.<br><br>To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Mailgun documentation</a>.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailgun</a> është një shërbim transaksionesh email-esh që ofron një provë bujare falas prej 3 muajsh. Pas saj, ofron një plan “Paguani Teksa Rriteni”, i cili ju lejon të paguani për aq sa përdorni, pa detyrim për ndonjë tarifë të fiksuar mujore.<br><br>Për t’ia filluar, lexoni <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për Mailgun-in</a>.','Hide the WP Mail SMTP Dashboard Widget.'=>'Fshihe Widget-in e Pultit të WP Mail SMTP-së.','Hide warnings alerting of email delivery errors.'=>'Fshihi sinjalizimet që njoftojnë gabime dërgimi email-esh.','Hide plugin announcements and update details.'=>'Fshihi njoftimet nga shtojca dhe hollësi përditësimesh.','Stop sending all emails'=>'Resht dërgimin e krejt email-eve','Export logs to CSV, XLSX, or EML'=>'Eksportoni regjistra si kartela CSV, XLSX, ose EML','User activated their new site, or site was added from Network Admin -> Sites -> Add New. Sent to Site Admin.'=>'Përdoruesi aktivizoi sajtin e vet të ri, ose sajti u shtua që nga Përgjegjës Rrjeti -> Sajte -> Shtoni të Ri. Dërguar Përgjegjësit të Sajtit.','Site Admin: Activated / Added Site'=>'Përgjegjësi Sajti: Aktivizo / Shtoi Sajt','User activated their new site, or site was added from Network Admin -> Sites -> Add New. Sent to Network Admin.'=>'Përdoruesi aktivizoi sajtin e vet të ri, ose sajti u shtua që prej Përgjegjës Rrjeti -> Sajte -> Shtoni të Ri. Dërguar Përgjegjësit të Rrjetit.','Network Admin: User Activated / Added Site'=>'Përgjegjës Rrjeti: Përdoruesi Aktivizoi / Shtoi Sajt','User registered for a new site. Sent to the site admin.'=>'Regjistrim përdoruesi për një sajt të ri. Dërguar përgjegjësit të sajtit.','User Created Site'=>'Sajt i Krijuar Nga Përdoruesi','New Site'=>'Sajt i Ri','A user has been added, or their account activation has been successful. Sent to the user, that has been added/activated.'=>'Është shtuar një përdorues, ose aktivizimi i llogarisë së tij qe i suksesshëm. Dërguar përdoruesit që u shtua/aktivizua.','Added / Activated on Site'=>'Shtuar / Aktivizuar në Sajt','A new user account was created. Sent to Network Admin.'=>'U krijua një llogari e re përdoruesi. Dërguar Përgjegjësit të Rrjetit.','Created On Site'=>'Krijuar Në Sajt','A new user was invited to a site from Users -> Add New -> Add New User. Sent to the invited user.'=>'Te një sajt u ftua një përdorues i ri, që nga Përdorues -> Shtoni të Ri -> Shtoni Përdorues të Ri. Dërguar përdoruesit të ftuar.','Invited To Site'=>'Ftuar Në Sajt','A new user was created. Sent to the new user.'=>'U krijua një përdorues i ri. U dërgua te përdoruesi i ri.','Created (User)'=>'U krijua (Përdoruesi)','A new user was created. Sent to the site admin.'=>'U krijua një përdorues i ri. Dërguar përgjegjësit të sajtit.','Created (Admin)'=>'U krijua (Përgjegjësi)','New User'=>'Përdorues i Ri','Full log of background update results which includes information about WordPress core, plugins, themes, and translations updates. Only sent when you are using a development version of WordPress. Sent to the site or network admin.'=>'Regjistër i plotë i përfundimeve të përditësimeve në prapaskenë, ku përfshihen hollësi mbi përditësime të bazës, shtojcave, temave dhe përkthimeve të WordPress-it. Dërguar vetëm kur përdorni një version zhvillim të WordPress-it. Dërguar përgjegjësit të sajtit ose rrjetit.','Full Log'=>'Regjistër i Plotë','Completion or failure of a background automatic core update. Sent to the site or network admin.'=>'Plotësim ose dështim i një përditësimi të automatizuar të bazës, zhvilluar në prapaskenë. Dërguar përgjegjësit të sajtit ose rrjetit.','WP Core Status'=>'Gjendje e Bazës së WP-së','Completion or failure of a background automatic theme update. Sent to the site or network admin.'=>'Plotësim ose dështim i një përditësimi të automatizuar të një teme, zhvilluar në prapaskenë. Dërguar përgjegjësit të sajtit ose rrjetit.','Theme Status'=>'Gjendje Teme','Completion or failure of a background automatic plugin update. Sent to the site or network admin.'=>'Plotësim ose dështim i një përditësimi të automatizuar të një shtojce, zhvilluar në prapaskenë. Dërguar përgjegjësit të sajtit ose rrjetit.','Plugin Status'=>'Gjendje Shtojce','Automatic Updates'=>'Përditësime të Vetvetishme','Disabling this option will block users from being able to export their personal data, as they will not receive an email with a link.'=>'Çaktivizimi i kësaj mundësie do t’u bllokojë përdoruesve të jenë në gjendje të eksportojnë të dhënat e tyre personale, ngaqë s’do të marrin email me një lidhje për këtë.','Site admin clicked "Email Data" button next to a confirmed data export request. Sent to the requester email address.'=>'Përgjegjës sajti klikoi mbi butonin “Dërgoji të Dhënat Me Email” në krah të një kërkese të ripohuar për fshirje të dhënash. Dërguar te adresa email e kërkuesit.','Admin Sent Link to Export Data'=>'Përgjegjësi Dërgoi Lidhje për Eksportim të Dhënash','Site admin clicked "Erase Personal Data" button next to a confirmed data erasure request. Sent to the requester email address.'=>'Përgjegjës sajti klikoi mbi butonin “Fshi të Dhëna Personale” në krah të një kërkese të ripohuar për fshirje të dhënash. Dërguar te adresa email e kërkuesit.','Admin Erased Data'=>'Të dhëna të Fshira nga Përgjegjësi','User clicked a confirmation link in personal data export or erasure request email. Sent to the site or network admin.'=>'Përdoruesi klikoi një lidhje ripohimi te një email eksportimi ose fshirjeje të dhënash personale. Dërguar përgjegjësit të sajtit ose të rrjetit.','User Confirmed Export / Erasure Request'=>'Përdoruesi Ripohoi Kërkesë Eksportimi / Fshirjeje','Personal Data Requests'=>'Kërkesa të Dhënash Personale','User changed their email address. Sent to the user.'=>'Përdoruesi ndryshoi adresën e tij email. Dërguar përdoruesit.','Email Changed'=>'U ndryshua email','User attempted to change their email address. Sent to the proposed new email address.'=>'Përdoruesi u përpoq të ndryshojë adresën e vet email. Dërguar te adresa e re email e propozuar.','Email Change Attempt'=>'Përpjekje Ndryshimi Email','User changed their password. Sent to the user.'=>'Përdorues ndryshoi fjalëkalimin e vet. Dërguar përdoruesit.','Password Changed'=>'Fjalëkalimi Ndryshoi','User reset their password from the password reset link. Sent to the site admin.'=>'Përdorues ricaktoi fjalëkalimin e vet që prej lidhjes për ricaktim fjalëkalimi. Dërguar përgjegjësit të sajtit.','Password Reset Successfully'=>'Fjalëkalimi u Ricaktua Me Sukses','User requested a password reset via "Lost your password?". Sent to the user.'=>'Përdorues kërkoi ricaktim fjalëkalimi përmes “Harruat fjalëkalimin tuaj?”. Dërguar përdoruesit.','Reset Password Request'=>'Kërkesë Ricaktimi Fjalëkalimi','Change of User Email or Password'=>'Ndryshim Email-i ose Fjalëkalimi Përdoruesi','Network admin email address was changed. Sent to the old network admin email address.'=>'Adresa email e përgjegjësit të sajtit u ndryshua. Dërguar te adresa e vjetër email e përgjegjësit të sajtit.','Network Admin Email Changed'=>'U ndryshua Email Përgjegjësi Rrjeti','Change of network admin email address was attempted. Sent to the proposed new email address.'=>'U provua të ndryshohej adresë email e përgjegjësit të rrjetit. Dërguar te adresa e re email e propozuar.','Network Admin Email Change Attempt'=>'Përpjekje për Ndryshim Email-i Përgjegjësi Rrjeti','Site admin email address was changed. Sent to the old site admin email address.'=>'Adresa email e përgjegjësit të sajtit u ndryshua. Dërguar te adresa e vjetër email e përgjegjësit të sajtit.','Site Admin Email Changed'=>'Email-i i Përgjegjësit të Sajtit Ndryshoi','Change of site admin email address was attempted. Sent to the proposed new email address.'=>'U provua të ndryshohej adresë email e përgjegjësit të sajtiti. Dërguar te adresa e re email e propozuar.','Site Admin Email Change Attempt'=>'Përpjekje për Ndryshim Email-i Përgjegjësi Sajti','Change of Admin Email'=>'Ndryshim Email-i Përgjegjësi','Comment has been published. Sent to the post author.'=>'Komenti u botua. Dërguar autorit të postimit.','Published'=>'U botua','Comment is awaiting moderation. Sent to the site admin and post author if they can edit comments.'=>'Komenti është në pritje të moderimit. Dërguar përgjegjësit të sajtit dhe autorit të postimit, nëse munden të përpunojnë komente.','Awaiting Moderation'=>'Në Pritje të Moderimit','Comments'=>'Komente','Outlook / 365 requires an SSL certificate, and so is not currently compatible with your site. Please contact your host to request a SSL certificate, or check out '=>'Outlook / 365 lyp një dëshmi SSL, ndaj s’është i përputhshëm me sajtin tuaj. Ju lutemi, lidhuni me strehuesin e sajtit tuaj për t’i kërkuar një dëshmi SSL, ose shihni ','If you\'d prefer not to set up SSL, or need an SMTP solution in the meantime, please go back and select a different mailer option.'=>'Nëse do të parapëlqenit të mos ujdisnit SSL, ose ndërkohë ju duhet një zgjidhje SMTP, ju lutemi, kthehuni mbrapsht dhe përzgjidhni një tjetër mundësi postuesi.','WPBeginner\'s tutorial on how to set up SSL'=>'Përkujdesore nga WPBeginner se si të ujdiset SSL-ja','Amazon SES requires an SSL certificate, and so is not currently compatible with your site. Please contact your host to request a SSL certificate, or check out '=>'Amazon SES lyp një dëshmi SSL, ndaj s’është i përputhshëm me sajtin tuaj. Ju lutemi, lidhuni me strehuesin e sajtit tuaj për t’i kërkuar një dëshmi SSL, ose shihni ','Read how to set up Postmark'=>'Lexoni si të ujdiset Postmark-u','Message Stream ID is <strong>optional</strong>. By default <strong>outbound</strong> (Default Transactional Stream) will be used. More information can be found in our %1$sPostmark documentation%2$s.'=>'ID Rrjedhe Mesazhesh është <strong>opsional</strong>. Si parazgjedhje, do të përdoret <strong>outbound</strong> (Rrjedhë Parazgjedhje Transaksionale). Më tepër hollësi mund të gjendet te %1$sdokumentimi ynë për Postmark-un%2$s.','%1$sFollow this link%2$s to get a Server API Token for Postmark.'=>'Që të merrni një Token API Shërbyesi për Postmark-un, %1$sndiqni këtë lidhje%2$s .','Message Stream ID'=>'ID Rrjedhe Mesazhesh','Server API Token'=>'Token API shërbyesi','Test HTML email was sent successfully! Please check your inbox to make sure it was delivered.'=>'Email-i provë në HTML u dërgua me sukses! Ju lutemi, kontrolloni email-et tuaj, për t’u siguruar se qe dërguar.','WP Core'=>'WP Core','Upgrade to <b>WP Mail SMTP Pro</b> and unlock <u>Email Log</u> and advanced <u>Email Reports</u>. Start measuring the success of your emails today!'=>'Përmirësojeni me <b>WP Mail SMTP Pro-në</b> dhe shkyçni <u>Regjistër Email-esh</u> dhe <u>Raporte të thelluara Email-esh</u>. Filloni të matni që sot suksesin e email-eve tuaja!','Want More Stats?'=>'Dëshironi Më Tepër Statistika?','Reports'=>'Raportime','Last week'=>'Java e fundit','Total Emails'=>'Email-e Gjithsej','Hi there,'=>'Njatjeta,','how to disable it'=>'si të çaktivizohet','This email was auto-generated and sent from %1$s. Learn %2$s.'=>'Ky email qe prodhuar automatikisht dhe dërguar prej %1$s. Mësoni %2$s.','WP Mail SMTP Logo'=>'Stemë e WP Mail SMTP','WP Mail SMTP Weekly Email Summary'=>'Përmbledhje Javore Email-esh, nga WP Mail SMTP','Your Weekly WP Mail SMTP Summary for %s'=>'Përmbledhja Juaj Javore për Email-e, nga WP Mail SMTP, për %s','You currently have the <strong>Default (none)</strong> mailer selected, which won\'t improve email deliverability. Please select <a href="%1$s" target="_blank" rel="noopener noreferrer">any other email provider</a> and use the easy <a href="%2$s">Setup Wizard</a> to configure it.'=>'Aktualisht keni të përzgjedhur postuesin <strong>Parazgjedhje (asnjë)</strong>, çka s’do ta përmirësojë shkallën e dërgimit të email-eve. Ju lutemi, përzgjidhni <a href="%1$s" target="_blank" rel="noopener noreferrer">cilindo shërbim tjetër email-esh</a> dhe për ta formësuar, përdorni <a href="%2$s">Ndihmësin e kollajtë të Ujdisjes</a>.','An email request was sent to the Gmail API.'=>'U dërgua një kërkesë email te API e Gmail-it.','An error occurred when trying to get Gmail aliases: %s'=>'Ndodhi një gabim kur provohej të merreshin aliase Gmail: %s','There was an error while processing Google authorization: missing code or scope parameter.'=>'Pati një gabim teksa përpunohej autorizim Google: kod ose parametër fushëveprimi që mungon.','There was an error while processing Google authorization: %s'=>'Pati një gabim teksa përpunohej autorizim Google: %s','There was an error while upgrading the %1$s database. Please contact %2$s support with this information: %3$s.'=>'Pati një gabim teksa përmirësohej baza e të dhënave %1$s. Ju lutemi, lidhuni me asistencën e %2$s me këto hollësi: %3$s.','An email request was sent.'=>'U dërgua një kërkesë email.','For more details please try running an Email Test or reading the latest <a href="%s">error event</a>.'=>'Për më tepër hollësi, ju lutemi, provoni të xhironi një Provë Email-i, ose të lexoni <a href="%s">aktin e fundit me gabim</a>.','<strong>Heads up!</strong> The last email your site attempted to send was unsuccessful.'=>'<strong>Vini re!</strong> Email-i i fundit që sajti juaj provoi të dërgonte që i pasuksesshëm.','Send Another Test Email'=>'Dërgo Një Tjetër Email Provë','Success!'=>'Sukses!','View Email Summary Example'=>'Shihni Shembull Përmbledhjeje Email-esh','Please enable <a href="%s">Email Logging</a> first, before this setting can be configured.'=>'Para se të mund të formësohet y rregullim, ju lutemi, së pari aktivizoni <a href="%s">Regjistrim Email-esh</a>.','Disable Email Summaries weekly delivery.'=>'Çaktivizo dërgim Përmbledhjesh javore Email-esh.','Disable Email Summaries'=>'Çaktivizo Përmbledhje Email-esh','Print email logs or save as PDF'=>'Shtypni regjistra email-esh ose ruajini si PDF','Track email opens and clicks'=>'Ndiq hapje dhe klikime të email-eve','Resend emails and attachments'=>'Ridërgo email-e dhe bashkëngjitje','See sent and failed emails'=>'Shihni email-e të dërguar dhe të dështuar','Save detailed email headers'=>'Ruaj krye të hollësishme të email-eve','Unlock these awesome logging features:'=>'Shkyçni këto veçori të mahnitshme regjistrimi:','Individual Email Log'=>'Regjistër Individual Email-esh','Email Log Index'=>'Tregues Regjistri Email-esh','See email report graphs in WordPress'=>'Shihni grafikë raportesh email-esh në WordPress','Spot failed emails quickly'=>'Pikasni shpejt email-e të dështuar','Measure open rate and click through rates'=>'Matni shkallë hapjesh dhe klikimi mbi to','Track total emails sent each week'=>'Ndiqni email-e të dërguar gjithsej çdo javë','View stats grouped by subject line'=>'Shihni statistika të grupuara sipas rreshtash subjekti','Get weekly deliverability reports'=>'Merrni raporte të përjavshëm shkalle dërgimi','Unlock these awesome reporting features:'=>'Shkyçni këto veçori të mahnitshme raportimi:','Weekly Email Report'=>'Raport i Përjavshëm i Email-eve','Detailed Stats by Subject Line'=>'Statistika të Hollësishme sipas Rreshtash Subjekti','Stats at a Glance'=>'Statistika Me një Vështrim','Email Reports'=>'Raporte Email-esh','For some reason the database table was not installed correctly. Please contact plugin support team to diagnose and fix the issue.'=>'Për ndonjë arsye, tabela e bazës së të dhënave s’qe instaluar saktë. Ju lutemi, lidhuni me ekipin e asistencës për shtojcën që të diagnostikojnë dhe ndreqni problemin.','Debug Events are Not Installed Correctly'=>'Pjesët e Diagnostikimeve s’janë instaluar saktësisht','between %1$s and %2$s'=>'mes %1$s dhe %2$s','on %s'=>'më %s','where event contains "%s"'=>'ku akti përmban "%s"','Search Events'=>'Kërkoni Te Akte','Found <strong>%1$s %2$s event</strong>'=>'U gjet <strong>%1$s akt %2$s</strong>' . "\0" . 'U gjetën <strong>%1$s akte %2$s</strong>','Check this if you would like to debug the email sending process. Once enabled, all debug events will be logged in the table below. This setting should only be enabled for shorter debugging periods and disabled afterwards.'=>'I vini shenjë kësaj, nëse do të donit të diagnostikohet procesi i dërgimit të email-eve. Pasi të jetë aktivizuar, krejt aktet e diagnostikimit do të regjistrohen te tabela më poshtë. Ky rregullim duhet aktivizuar vetëm për periudha të shkurtra diagnostikimi dhe më pas të çaktivizohet.','Debug Email Sending'=>'Diagnostiko Dërgim Email-esh','This debug event is always enabled and will record any email sending errors in the table below.'=>'Ky akt diagnostikimi është përherë i aktivizuar dhe do të regjistrojë te tabela më poshtë çfarëdo gabimesh dërgimi email-esh.','Email Sending Errors'=>'Gabime Dërgimi Email-sh','Event Types'=>'Lloje Aktesh','On this page, you can view and configure different plugin debugging events. View email sending errors and enable debugging events, allowing you to detect email sending issues.'=>'Në këtë faqe, mund të shihni dhe formësoni akte të ndryshme diagnostikimi të shtojcës. Shihni gabime dërgimi email-esh dhe aktivizoni akte diagnostikim, çka ju lejon të pikasni probleme dërgimi email-esh.','An error occurred!'=>'Ndodhi një gabim!','Close'=>'Mbylle','Are you sure you want to permanently delete all debug events?'=>'Jeni i sigurt se doni të fshihen përgjithmonë krejt aktet e diagnostikimit?','Debug Events'=>'Diagnostikim Aktesh','Suggest a Feature'=>'Sugjeroni një Veçori','Follow on Facebook'=>'Ndiqnani në Facebook','Support & Docs'=>'Asistencë & Dokumentim','See Quick Links'=>'Shihni Lidhje të Shpejta','Delete All Events'=>'Fshiji Krejt Aktet','Filter'=>'Filtro','No events have been logged for now.'=>'Hëpërhë s’janë regjistruar akte.','No events found.'=>'S’u gjetën veprimtari.','Event'=>'Akt','All'=>'Krejt','Email Source: %s'=>'Burim Email-i: %s','%1$s (line: %2$s)'=>'%1$s (rreshti: %2$s)','Content'=>'Lëndë','Date'=>'Datë','Debug Event Details'=>'Hollësi Diagnostikimi Akti','N/A'=>'N/A','Event #%d'=>'Akt #%d','Number of events per page:'=>'Numër aktesh për faqe:','No Debug Event ID provided!'=>'S’u dha ID Akti Diagnostikimi!','There was an issue while trying to delete all debug event entries. Error message: %s'=>'Pati një problem teksa provohej të fshiheshin krejt zërat për akte diagnostikimi. Mesazh gabimi: %s','All debug event entries were deleted successfully.'=>'Krejt zërat për akte diagnostikimi u fshinë me sukses.','You don\'t have the capability to perform this action.'=>'S’keni leje për të kryer këtë veprim.','Access rejected.'=>'Hyrja u hodh poshtë.','Weekly Email Summaries have been enabled'=>'Përmbledhjet Javore të Email-eve janë aktivizuar','View Example'=>'Shihni Shembull','<b>NEW!</b> Enable Weekly Email Summaries'=>'<b>E RE!</b> Aktivizoni Përmbledhje Javore Email-esh','We believe in full transparency. The Sendinblue links above are tracking links as part of our partnership with Sendinblue. We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Besojmë në transparencën e plotë. Lidhjet Sendinblue më sipër janë lidhje gjurmimi, si pjesë e bashkëpunimit tonë me Sendinblue-në. Mund të rekomandojmë thuajse cilindo shërbim SMTP, por mund të rekomandojmë vetëm produkte që besojmë se do të shtojnë vlerë për përdoruesit tanë.','We believe in full transparency. The SMTP.com links above are tracking links as part of our partnership with SMTP (j2 Global). We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Besojmë në transparencën e plotë. Lidhjet SMTP.com më sipër janë lidhje gjurmimi, si pjesë e bashkëpunimit tonë me SMTP-në (j2 Global). Mund të rekomandojmë thuajse cilindo shërbim SMTP, por mund të rekomandojmë vetëm produkte që besojmë se do të shtojnë vlerë për përdoruesit tanë.','Transparency and Disclosure'=>'Transparencë dhe Klauzola','Enhanced Weekly Email Summary'=>'Përmbledhje e Zgjeruar Javore Email-esh','Get statistics about emails you\'ve sent.'=>'Merrni statistika mbi email-et që keni dërguar.','Weekly Email Summary'=>'Përmbledhje Javore Email-esh','Read how to set up Microsoft Outlook / 365'=>'Lexoni si të ujdiset Microsoft Outlook / 365','Or disable the Sendinblue email sending setting in WooCommerce > Settings > Sendinblue (tab) > Email Options (tab) > Enable Sendinblue to send WooCommerce emails.'=>'Ose çaktivizoni rregullimin për dërgim email-esh me Sendinblue, te WooCommerce > Rregullime > Sendinblue (skedë) > Mundësi Email-i (skedë) > Aktivizoni Sendinblue për dërgim email-esh WooCommerce.','Lite vs Pro'=>'Lite vs. Pro','Hide Dashboard Widget'=>'Fshih Widget Pulti','Email Addresses'=>'Adresa email','Search'=>'Kërkim','Select a date range'=>'Përzgjidhni një interval datash','Custom Date Range'=>'Interval Vetjak Datash','Email log ID'=>'ID regjistri email-esh','Error Details'=>'Hollësi Gabimi','Headers'=>'Krye','Blind Carbon Copy (BCC)'=>'Kopje Karbon e Verbër (BCC)','Carbon Copy (CC)'=>'Kopje Karbon (CC)','Additional Information'=>'Informacion Shtesë','Attachments'=>'Bashkëngjitje','Number of Attachments'=>'Numër Bashkëngjitjesh','Created Date'=>'Datë Krijimi','Body'=>'Lëndë','Subject'=>'Subjekt','From Address'=>'Adresë Nga','To Address'=>'Adresë Për','Common Information'=>'Hollësi të Rëndomta','Export in EML (.eml)'=>'Eksportoje si EML (.eml)','Export in Microsoft Excel (.xlsx)'=>'Eksportoje si Microsoft Excel (.xlsx)','Export in CSV (.csv)'=>'Eksportoje si CSV (.csv)','Export Type'=>'Lloj Eksportimi','Export Email Logs'=>'Eksporto Regjistra Email-esh','Export'=>'Eksportim','Search results for <strong>%s</strong>'=>'Përfundime kërkimi për <strong>%s</strong>','Action Scheduler library is also used by other plugins, like WPForms and WooCommerce, so you might see tasks that are not related to our plugin in the table below.'=>'Biblioteka e Planifikuesit të Veprimeve përdoret edhe nga shtojca të tjera, bie fjala, WPForms dhe WooCommerce, ndaj te tabela më poshtë mund të shihni akte që nuk lidhen me shtojcën tonë.','WP Mail SMTP is using the <a href="%s" target="_blank" rel="noopener noreferrer">Action Scheduler</a> library, which allows it to queue and process bigger tasks in the background without making your site slower for your visitors. Below you can see the list of all tasks and their status. This table can be very useful when debugging certain issues.'=>'WP Mail SMTP po përdor bibliotekën <a href="%s" target="_blank" rel="noopener noreferrer">Planifikues Veprimesh</a>, që ju lejon të vini në radhë dhe kryeni në prapaskenë akte më të mëdha, pa e ngadalësuar sajtin tuaj për vizitorët. Më poshtë mund të shihni listën e krejt akteve dhe gjendjen e tyre. Kjo tabelë mund të jetë shumë e dobishme kur diagnostikohen disa probleme.','Scheduled Actions'=>'Veprime të Planifikuar','Notifications'=>'Njoftime','Sent %s'=>'Të dërguar %s','Failed %s'=>'Të dështuar %s','Unconfirmed %s'=>'Të paripohuar %s','Confirmed %s'=>'Të ripohuar %s','%d total'=>'%d gjithsej','Table cell icon'=>'Ikonë kutie tabele','WordPress'=>'WordPress','Color Scheme'=>'Skemë Ngjyrash','Line'=>'Vijë','Bar'=>'Shtyllë','Graph Style'=>'Stil Grafiku','All Emails'=>'Krejt Email-et','Select email type'=>'Përzgjidhni lloj email-i','Sent Emails'=>'Email-e të Dërguar','Failed Emails'=>'Email-e të Dështuar','Unconfirmed Emails'=>'Email-e të Paripohuar','Confirmed Emails'=>'Email-e të Ripohuar','Last %d day'=>'%d ditën e fundit' . "\0" . '%d ditët e fundit','All Time'=>'Tërë Kohën','Select timespan'=>'Përzgjidhni shtrirje kohore','<a href="%s" target="_blank" rel="noopener noreferrer">Upgrade to Pro</a> for detailed stats, email logs, and more!'=>'Për statistika të hollësishme, regjistra email-i dhe të tjera, <a href="%s" target="_blank" rel="noopener noreferrer">Përmirësojeni me versionin Pro</a>!','Automatically keep track of every email sent from your WordPress site and view valuable statistics right here in your dashboard.'=>'Ndiqni automatikisht çdo email të dërguar nga sajti juaj WordPress dhe shihni statistika të vyera drejt e nga pulti juaj.','View Detailed Email Stats'=>'Shihni Statistika të Hollësishme Email-esh','There was an error while processing the authentication request. Please recheck your Region, Client ID and Client Secret and try again.'=>'Pati një gabim teksa përpunohej kërkesa për mirëfilltësim. Ju lutemi, rikontrolloni Rajonin tuaj, ID-në tuaj të Klientit dhe të Fshehtën e Klientit dhe riprovoni.','Email domain issues detected'=>'U pikasën probleme përkatësie email-i','All checks for your email domain were successful. It looks like everything is configured correctly.'=>'Krejt kontrollet për përkatësinë tuaj email qenë të suksesshëm. Duket se gjithçka është formësuar saktë.','Email domain is configured correctly'=>'Përkatësia email është formësuar saktë','Current from email domain'=>'Aktuale prej përkatësie email','Is email domain configured properly?'=>'A është formësuar si duhet përkatësia email?','Unable to write in WPMailSMTP upload directory %s. Is it writable by the server?'=>'S’arrihet të shkruhet në drejtorinë WPMailSMTP të ngarkimeve %s. Është e shkrueshme nga shërbyesi?','Unable to create directory %s. Is its parent directory writable by the server?'=>'S’arrihet të krijohet drejtoria %s. A është e shkrueshme nga shërbyesi drejtoria mëmë?','Tools'=>'Mjete','You can also send emails with different From Email addresses, by disabling the Force From Email setting and using registered aliases throughout your WordPress site as the From Email addresses.'=>'Mund të dërgoni email-e edhe me adresa të tjera Email Nga, duke çaktivizuar rregullimin “Detyro Email Nga” dhe duke përdorur aliase të regjistruar në sajtin tuaj WordPress si adresa Email Nga.','We\'ll guide you through each step needed to get WP Mail SMTP fully set up on your site.'=>'Do t’ju udhëheqim për çdo hap të nevojshëm për ta pasur plotësisht të ujdisur WP Mail SMTP në sajtni tuaj.','Launch Setup Wizard'=>'Nis Ndihmësin e Ujdisjes','Boost your sales and conversions by up to 15% with real-time social proof notifications. TrustPulse helps you show live user activity and purchases to help convince other users to purchase.'=>'Shtoni shitjet dhe shndërrimet tuaja deri në 15% përmes njoftimesh të atypëratyshme në rrjete shoqërore. TrustPulse-i ju ndihmon të shfaqni aty për aty veprimtari dhe blerje nga përdorues, për të ndihmuar të binden përdorues të tjerë të blejnë.','TrustPulse'=>'TrustPulse','Easily display Twitter content in WordPress without writing any code. Comes with multiple layouts, ability to combine multiple Twitter feeds, Twitter card support, tweet moderation, and more.'=>'Shfaqni kollaj lëndë Twitter në WordPress, pa shkruar kod. Vjen me skema të ndryshme, aftësinë për të ndërthurur shumë prurje Twitter, mbulim për skeda Twitter, moderim tweet-esh, etj.','Smash Balloon Twitter Feeds'=>'Prurje “Smash Balloon” për Twitter','Easily display YouTube videos on your WordPress site without writing any code. Comes with multiple layouts, ability to embed live streams, video filtering, ability to combine multiple channel videos, and more.'=>'Shfaqni kollaj video YouTube në sajtin tuaj WordPress, pa shkruar kod fare. Vjen me shumë skema, me aftësinë për të trupëzuar transmetime të drejtpërdrejta, filtrim videosh, aftësinë për të ndërthurur shumë kanale video, etj.','Smash Balloon YouTube Feeds'=>'Prurje “Smash Balloon” për YouTube','Easily display Facebook content on your WordPress site without writing any code. Comes with multiple templates, ability to embed albums, group content, reviews, live videos, comments, and reactions.'=>'Shfaqni kollaj lëndë Facebook-u në sajtin tuaj WordPress, pa shkruar fare kod. Vjen me gjedhe të shumta, aftësinë për të trupëzuar albume, grupim lënde, shqyrtime, video drejtpërsëdrejti, komente dhe reagime.','Smash Balloon Facebook Feeds'=>'Prurje “Smash Balloon” për Facebook','Easily display Instagram content on your WordPress site without writing any code. Comes with multiple templates, ability to show content from multiple accounts, hashtags, and more. Trusted by 1 million websites.'=>'Shfaqni kollaj lëndë Instagram në sajtin tuaj WordPress, pa shkruar fare kod. Vjen me gjedhe të shumta, aftësinë për të shfaqur lëndë nga shumë llogari, hashtag-e, etj. E besuar nga 1 milionë sajte.','Smash Balloon Instagram Feeds'=>'Prurje “Smash Balloon” për Instagram','Connect with your visitors after they leave your website with the leading web push notification software. Over 10,000+ businesses worldwide use PushEngage to send 15 billion notifications each month.'=>'Lidhuni me vizitorët tuaj, pasi ikin prej sajtit tuaj, përmes një software-i kryesues njoftimesh push. Mbi 10 mijë biznese e përdorin PushEngage-in për të dërgua 15 miliardë njoftime çdo muaj.','PushEngage'=>'PushEngage','Turn your website visitors into brand ambassadors! Easily grow your email list, website traffic, and social media followers with the most powerful giveaways & contests plugin for WordPress.'=>'Shndërrojini vizitorët e sajteve tuaj në ambasadorë markash! Shtoni lehtësisht listën tuaj të email-eve, trafikun në saj, dhe ndjekësit në media shoqërore, me shtojcën më të mirë WordPress për dhurata & gara.','The fastest drag & drop landing page builder for WordPress. Create custom landing pages without writing code, connect them with your CRM, collect subscribers, and grow your audience. Trusted by 1 million sites.'=>'Krijuesi më i shpejtë i faqeve me teknikën “merr dhe vër” për WordPress. Krijoni faqe vetjake ardhjeje, pa shkruar kod, lidhini ato me platoformën tuaj CRM, mblidhni pajtimtarë, dhe shtoni publikun tuaj. E besuar nga 1 milionë sajte.','SeedProd'=>'SeedProd','The original WordPress SEO plugin and toolkit that improves your website’s search rankings. Comes with all the SEO features like Local SEO, WooCommerce SEO, sitemaps, SEO optimizer, schema, and more.'=>'Shtojca dhe grupi i mjeteve origjinale WordPress për SEO, që përmirësojnë radhitjen në kërkime të sajtit tuaj. Vjen me krejt veçoritë për SEO, të tilla si Local SEO, WooCommerce SEO, harta sajtash, optimizues SEO, skema, etj.','AIOSEO'=>'AIOSEO','The leading WordPress analytics plugin that shows you how people find and use your website, so you can make data driven decisions to grow your business. Properly set up Google Analytics without writing code.'=>'Shtojca WordPress kryesuese për analiza që tregon se sa vetë e gjejnë dhe përdorin sajtin tuaj, që kështu të merrni vendime të bazuara në të dhëna, për fuqizimin e biznesit tuaj. Ujdisni si duhet Google Analytics, pa shkruar kod fare.','The best drag & drop WordPress form builder. Easily create beautiful contact forms, surveys, payment forms, and more with our 600+ form templates. Trusted by over 5 million websites as the best forms plugin.'=>'Krijuesi më i mirë “merr dhe vër” i formularëve WordPress. Krijoni kollaj formularë të hijshëm kontaktesh, pyetësorë, formularë pagesash, etj, me mbi 100 gjedhet tona për formularë. E besuar nga mbi 4 milionë sajte si shtojca më e mirë për formularë.','Instantly get more subscribers, leads, and sales with the #1 conversion optimization toolkit. Create high converting popups, announcement bars, spin a wheel, and more with smart targeting and personalization.'=>'Përfitoni menjëherë më tepër pajtimtarë, shndërrime në klientë dhe shitje, me grupin numër një të mjeteve për optimizim shndërrimesh. Krijoni flluska shndërrimi, shtylla njoftimesh, rrotullame, etj, ne fokusim dhe personalizim të mençur.','Copied'=>'U kopjua','Copy Error Log'=>'Kopjoni Regjistër Gabimesh','View Full Error Log'=>'Shiheni të Plotë Regjistrin e Gabimeve','Please copy the error log message below into the support ticket.'=>'Ju lutemi, kopjojeni mesazhin prej regjistri gabimesh më poshtë në një çështje për asistencën.','You have successfully linked the current site with your Microsoft API project. Now you can start sending emails through Outlook.'=>'E keni lidhur me sukses sajtin e tanishëm me projektin tuaj për API Microsoft. Tani mund të filloni të dërgoni email-e përmes Outlook-ut.','Already purchased? Enter your license key below to connect with %1$sWP Mail SMTP Pro%2$s!'=>'Është blerë tashmë? Jepni më poshtë kyçin tuaj të licencës, që të bëhet lidhja me %1$sWP Mail SMTP Pro%2$s!','Please input the sending domain/subdomain you configured in your Sendinblue dashboard. More information can be found in our %1$sSendinblue documentation%2$s'=>'Ju lutemi, jepni përkatësinë/nënpërkatësinë e dërgimit që formësuat te pulti juaj në Sendinblue. Më tepër të dhëna mund të gjenden te  %1$sdokumentimi ynë për Sendinblue%2$s','Please input the sending domain/subdomain you configured in your SendGrid dashboard. More information can be found in our %1$sSendGrid documentation%2$s'=>'Ju lutemi, jepni përkatësinë/nënpërkatësinë e dërgimit që formësuat te pulti juaj në SendGrid. Më tepër të dhëna mund të gjenden te  %1$sdokumentimi ynë për SendGrid%2$s','The following plugin will be installed for free: WPForms'=>'Shtojca vijuese do të instalohet falas: WPForms','You\'re currently using %1$sWP Mail SMTP Lite%2$s - no license needed. Enjoy!'=>'Aktualisht po përdorni %1$sWP Mail SMTP Lite%2$s - s’ka nevojë për licencë. Kënaquni!','Continue'=>'Vazhdo','Paste your license key here'=>'Hidhni këtu kyçin tuaj të licencës','Before continuing, you\'ll need to allow this plugin to send emails using your %s account.'=>'Para se të vazhdohet, do t’ju duhet të lejoni këtë shtojcë të dërgojë email-e duke përdorur llogarinë tuaj %s.','Return to Plugin Settings'=>'Kthehu te Rregullimet e Shtojcës','Upgrade Failed!'=>'Përmirësimi Dështoi!','Successful Upgrade!'=>'Përmirësim i Suksesshëm!','Verification Error!'=>'Gabim Verifikimi!','Successful Verification!'=>'Verifikim i Suksesshëm!','Successful Authorization'=>'Autorizim i Suksesshëm','Authorization Error!'=>'Gabim Autorizimi!','Which mailer would you like to use to send emails? Not sure which mailer to choose? Check out our %1$scomplete mailer guide%2$s for details on each option.'=>'Cilin postues do të donit të përdorni për të dërguar email-e? S’jeni i sigurt cilin postues të zgjidhni? Për hollësi rreth çdo mundësie, shihni te %1$sudhërrëfyesi ynë i plotë për postuesit%2$s.','%1$s, %2$s'=>'%1$s, %2$s','Error Message:'=>'Mesazh Gabimi:','Please fill out all the required fields to continue.'=>'Ju lutemi, që të vazhdohet, plotësoni krejt fushat e domosdoshme.','Installed'=>'E instaluar','Value has to be a round number'=>'Vlera duhet të jetë një numër i plotë','Please enter a value between %1$s and %2$s'=>'Ju lutemi, jepni një vlerë mes %1$s dhe %2$s','Can\'t register the Amazon SES Identity'=>'S’regjistrohet dot Identitet Amazon SES','Can\'t retrieve Amazon SES Identities.'=>'S’merren dot Identitete Amazon SES.','It looks like we can\'t retrieve Amazon SES Identities.'=>'Duket sikur s’mund të marrim Identitete Amazon SES.','It looks like we can\'t load the settings.'=>'Duket sikur s’mund të ngarkojmë rregullimet.','It looks like we can\'t load authentication details.'=>'Duket sikur s’mund të ngarkojmë hollësi mirëfilltësimi.','Network error encountered. SMTP plugin import failed!'=>'U has gabim rrjeti. Importimi i shtojcës SMTP dështoi!','It looks like we can\'t import the plugin settings.'=>'Duket sikur s’i importojmë dot rregullimet e shtojcës.','Network error encountered. Settings not saved.'=>'U has një gabim rrjeti. Rregullimet s’u ruajtën.','It looks like we can\'t save the settings.'=>'Duket sikur s’mund t’i ruajmë rregullimet.','License key input'=>'Dhënie kyçi licence','Pro badge'=>'Stemë Pro','Your license was successfully verified! You are ready for the next step.'=>'Licenca juaj u verifikua me sukses! Jeni gati për hapin pasues.','The License Key format is incorrect. Please enter a valid key and try again.'=>'Formati i Kyçit të Licencës është i pasaktë. Ju lutemi, jepni një kyç të vlefshëm dhe riprovoni.','Verify License Key'=>'Verifikoni Kyç Licence','Enter your license key below to unlock plugin updates!'=>'Jepni më poshtë kyçin tuaj të licencës, që të zhbllokohen përditësime shtojce!Enter your license key below to unlock plugin updates!','To unlock selected features, %1$sUpgrade to Pro%2$s and enter your license key below.'=>'Që të shkyçen veçoritë e përzgjedhura, %1$sPërmirësojeni me Pro%2$s dhe jepni më poshtë kyçin tuaj të licencës.','Enter your WP Mail SMTP License Key'=>'Jepni kyçin tuaj të licencës për WP Mail SMTP','I\'ll do it later'=>'Do ta bëj më vonë','Purchase Now'=>'Blijeni Tani','These features are available as part of WP Mail SMTP Pro plan.'=>'Këto veçori janë pjesë e planit WP Mail SMTP Pro.','Would you like to purchase the following features now?'=>'Do të donit të blini veçoritë vijuese tani?','Rate on WordPress.org'=>'Vlerësonani në WordPress.org','Help us spread the word %1$sby giving WP Mail SMTP a 5-star rating %3$s(%4$s) on WordPress.org%2$s. Thanks for your support and we look forward to bringing you more awesome features.'=>'Ndihmoni të përhapet fjala %1$sduke i dhënë WP Mail SMTP nëj vlerësim me 5 yje %3$s(%4$s) në WordPress.org%2$s. Faleminderit për përkrahjen dhe presim t’ju sjellim më tepër veçori të mahnitshme.','Thanks for the feedback!'=>'Faleminderit për përshtypjet!','Star icon'=>'Ikonë yllth','%1$sBonus:%2$s You can upgrade to the Pro plan and %3$ssave %5$s today%4$s, automatically applied at checkout.'=>'%1$sBonus:%2$s Mund ta përmirësoni me planin Pro dhe të %3$skurseni %5$s që sot%4$s, aplikuar automatikisht gjatë përfundimit të blerjes.','Upgrade to Pro Today'=>'Përmirësojeni me Pro-n Që Sot','Upgrade to WP Mail SMTP Pro to unlock more awesome features and experience why WP Mail SMTP is used by over 4,000,000 websites.'=>'Përmirësojeni me WP Mail SMTP Pro që të shkyçen më tepër veçori të mrekullueshme dhe të shihni në punë e sipër pse WP Mail SMTP përdoret nga mbi 4 milionë sajte.','Upgrade to Unlock Powerful SMTP Features'=>'Që të Zhbllokohen Veçori të Fuqishme SMTP, Përmirësojeni','Check out our other free WordPress plugins:'=>'Provoni shtojca të tjera tonat falas për WordPress:','Here’s what to do next:'=>'Ja ç’të bëni në vazhdim:','Congrats, you’ve successfully set up WP Mail SMTP!'=>'Përgëzime, keni ujdisur me sukses WP Mail SMTP!','Our goal is to make your SMTP setup as simple and straightforward as possible. We\'d love to know how this process went for you!'=>'Synimi ynë është ta bëjmë ujdisjen e SMTP-së tuaj sa më të thjeshtë dhe më të drejtpërdrejtë që të jetë e mundur. Do të donim fort të dinim se si shkoi ky proces për ju!','How was your WP Mail SMTP setup experience?'=>'Si shkoi puna me ujdisjen tuaj të WP Mail SMTP-së?','Submit Feedback'=>'Parashtroni Përshtypjet','Yes, I give WP Mail SMTP permission to contact me for any follow up questions.'=>'Po, i jap WP Mail SMTP-së leje të lidhet me mua për çfarëdo pyetjesh në vazhdim.','We\'re sorry things didn\'t go smoothly for you, and want to keep improving. Please let us know any specific parts of this process that you think could be better. We really appreciate any details you\'re willing to share!'=>'Na vjen keq që gjërat s’ecën rrjedhshëm për ju, dhe duam të vazhdojmë t’i përmirësojmë. Ju lutemi, na bëni të ditur çfarëdo pjesësh të veçanta të këtij procesi që mendoni se mund të jenë më mirë. E vlerësojmë vërtet çfarëdo hollësie që do të donit të na jepnit!','What could we do to improve?'=>'Ç’mund të bëjmë për ta përmirësuar?','Save time with powerful WordPress Multisite controls.'=>'Kurseni kohë, me kontrolle të fuqishme për WordPress Shumësajtësh.','Multisite Network Settings'=>'Rregullime Rrjeti Shumësajtësh','Control which email notifications your WordPress site sends.'=>'Kontrolloni çfarë email-esh dërgon sajti juaj WordPress.','Manage Default Notifications'=>'Administroni Njoftime Parazgjedhje','Keep records of every email that\'s sent out from your website.'=>'Mbani regjistra të çdo email-i që keni dërguar nga sajti juaj.','Detailed Email Logs'=>'Regjistrime të Hollësishme Email-esh','Create beautiful contact forms with just a few clicks.'=>'Krijoni formularë të hijshëm kontaktesh vetëm me pak klikime.','Smart Contact Form'=>'Formular i Mençur Kontakti','Easily spot errors causing delivery issues.'=>'Pikasni kollaj gabime që shkaktojnë probleme dërgimi.','Email Error Tracking'=>'Ndjekje Gabimesh Email-i','Ensure your emails are sent successfully and reliably.'=>'Siguroni që email-et tuaj dërgohen me sukses dhe me qëndrueshmëri.','Improved Email Deliverability'=>'Shkallë Dërgimi e Përmirësuar Email-esh','Make sure you\'re getting the most out of WP Mail SMTP. Just check all of the features you\'d like to use, and we\'ll go ahead and enable those for you.'=>'Sigurohuni se po përfitoni maksimumin nga WP Mail SMTP. Thjesht u vini shenjë krejt veçorive që do të donit të përdornit, dhe do të ecim përpara dhe t’i aktivizojmë ato për ju.','Which email features do you want to enable?'=>'Cilat veçori email-i doni të aktivizohen?','Enable Auto TLS'=>'Aktivizo Auto TLS','Yes, count me in'=>'Po, më llogaritni edhe mua','Help make WP Mail SMTP better for everyone'=>'Ndihmoni të bëhet WP Mail SMTP më e mirë për këdo','Your email is needed, so you can receive recommendations.'=>'Email-i juaj duhet, që kështu të mund të merrni rekomandime.','Your Email Address'=>'Adresa Juaj Email','Get helpful suggestions from WP Mail SMTP on how to optimize your email deliverability and grow your business.'=>'Merrni sugjerime ndihmëse nga WP Mail SMTP se si të optimizoni shkallën e dërgimit të email-eve dhe të fuqizoni biznesin tuaj.','Help Improve WP Mail SMTP + Smart Recommendations'=>'Ndihmoni të Përmirësohet WP Mail SMTP + Rekomandimet e Mençura','Below, we\'ll show you all of the settings required to set up this mailer.'=>'Më poshtë, do t’ju tregojmë krejt rregullimet e domosdoshme për të ujdisur këtë postues.','Configure Mailer Settings'=>'Formësoni Rregullime Postuesi','Checking mailer configuration image'=>'Po kontrollohet pamje formësimi postuesi','We\'re running some tests in the background to make sure everything is set up properly.'=>'Na duhet të xhirojmë ca teste në prapaskenë për të garantuar që gjithçka është ujdisur si duhet.','Checking Mailer Configuration'=>'Po Kontrollohet Formësim Postuesi','You appear to be offline. Plugin information not retrieved.'=>'Duket se s’jeni i lidhur në internet. S’u mor informacion shtojce.','It looks like we can\'t fetch plugins information.'=>'Duket sikur s’mund të sjellim dot informacion të shtojcës.','Can\'t fetch plugins information.'=>'Nuk sillet dot informacion shtojve.','You appear to be offline. Plugin not installed.'=>'Duket se s’jeni i lidhur në internet. Shtojca s’u instalua.','It looks like we can\'t install the plugin.'=>'Duket sikur s’mund ta instalojmë shtojcën.','It looks like the plugin installation failed!'=>'Duket se instalimi i shtojcës dështoi!','You appear to be offline.'=>'Duket se s’jeni lidhur në internet.','It looks like we can\'t send the feedback.'=>'Duket sikur s’mund të dërgojmë përshtypjet.','It looks like we can\'t perform the mailer configuration check.'=>'Duket sikur s’mund të kryejmë kontroll të formësimit të postuesit.','Enter a valid email address. A verification email will be sent to the email address you entered.'=>'Jepni një adresë email të vlefshme. Te adresa që dhatë, do të dërgohet një email verifikimi.','Enter the domain name to verify it on Amazon SES and generate the required DNS CNAME records.'=>'Jepni emrin e përkatësisë për t’u verifikuar te Amazon SES dhe për të prodhuar zërin DNS CNAME të domosdoshëm.','Please enter a valid email address'=>'Ju lutemi, jepni një adresë email të vlefshme','Please enter a domain'=>'Ju lutemi, jepni një përkatësi','Verify Email Address'=>'Verifikoni Adresë Email','Verify Domain'=>'Verifikoni Përkatësi','Please add these CNAME records to your domain\'s DNS settings. For information on how to add CNAME DNS records, please refer to the %1$sAmazon SES documentation%2$s.'=>'Ju lutemi, shtojini këta zëra CNAME te rregullimet e DNS-së të përkatësisë tuaj. Për hollësi se si të shtohen zëra DNS CNAME, ju lutemi, referojuni %1$sdokumentimit të Amazon SES%2$s.','Value'=>'Vlerë','Name'=>'Emër','Add New SES Identity'=>'Shtoni Identitet SES të ri','Verify SES Identity'=>'Verifiko Identitet SES','Here are the domains and email addresses that have been verified and can be used as the From Email.'=>'Ja ku janë përkatësitë dhe adresat email që kemi verifikuar dhe mund të përdoren te fusha “Email Nga”.','Resend'=>'Ridërgoje','View DNS'=>'Shihni DNS','You will not be able to send emails until you verify at least one domain or email address for the selected Amazon SES Region.'=>'S’do të jeni në gjendje të dërgoni email-e, pa verifikuar të paktën një përkatësi ose adresë email për Rajonin Amazon SES të përzgjedhur.','No registered domains or emails.'=>'Pa përkatësi ose email-e të regjistruar.','Verify Email'=>'Verifikoni Email-in','Please check the inbox of <b>%s</b> for a confirmation email.'=>'Ju lutemi, për një email ripohimi, kontrolloni te posta e <b>%s</b>.','Connected as'=>'I lidhur si','Removing this OAuth connection will give you the ability to redo the OAuth connection or connect to different %s account.'=>'Heqja e kësaj lidhjeje OAuth do t’ju japë aftësinë të ribëni lidhjen OAuth ose të lidheni me një tjetër llogari %s.','If you want to use a different From Email address you can setup a Google email alias. %1$sFollow these instructions%2$s, then select the alias in the From Email section below.'=>'Nëse doni të përdoret një tjetër adresë “Email Nga”, mund të ujdisni një alias email-i Google. %1$sNdiqni këto udhëzime%2$s, mandej përzgjidhni aliasin që nga ndarja “Email Nga” më poshtë.','Connect to %s'=>'Lidhu te %s','There was an error while processing the authentication request. Please recheck your Client ID and Client Secret and try again.'=>'Pati një gabim teksa përpunohej kërkesa për mirëfilltësim. Ju lutemi, rikontrolloni ID-në tuaj të Klientit dhe të Fshehtën e Klientit dhe riprovoni.','The value entered does not match the required format'=>'Vlera e dhënë s’përputhet me formatin e domosdoshëm','Copied!'=>'U kopjua!','Copy input value'=>'Kopjo vlerën e dhënë','Step %1$s of %2$s'=>'Hapi %1$s nga %2$s','It looks like we can\'t load oAuth redirect.'=>'Duket sikur s’ngarkojmë dot ridrejtim oAuth.','It looks like we can\'t register the Amazon SES Identity.'=>'Duket sikur s’regjistrojmë dot Identitetin Amazon SES.','It looks like we can\'t retrieve the Amazon SES Identities.'=>'Duket sikur s’marrim dot Identitete Amazon SES.','It looks like we can\'t remove oAuth connection.'=>'Duket sikur s’heqim dot lidhje oAuth.','It looks like we can\'t load existing settings.'=>'Duket sikur s’ngarkojmë dot rregullime ekzistuese.','It looks like we can\'t load oAuth connected data.'=>'Duket sikur s’ngarkojmë dot të dhëna lidhjeje oAuth.','Read how to set up Sendgrid'=>'Lexoni si të ujdiset Sendgrid-i','To send emails you will need only a %1$sMail Send%2$s access level for this API key.'=>'Që të dërgoni email, do t’ju duhet vetëm një shkallë përdorimi %1$sMail Send%2$s për këtë kyç API.','%1$sFollow this link%2$s to get an API Key for Sendgrid.'=>'%1$sNdiqni këtë lidhje%2$s që të merrni një Kyç API për Sendgrid.','Read how to set up Amazon SES'=>'Lexoni si të ujdiset Amazon SES','Please select the Amazon SES API region which is the closest to where your website is hosted. This can help to decrease network latency between your site and Amazon SES, which will speed up email sending.'=>'Ju lutemi, përzgjidhni rajonin për API-n Amazon SES që është më i afërti për vendin ku strehohet sajti juaj. Kjo mund të ndihmojë të ulet vonesa në rrjet mes sajtit tuaj dhe Amazon SES, çka do të përshpejtojë dërgimin e email-eve.','SES Identities'=>'Identitete SES','Secret Access Key'=>'Kyç Hyrjeje të Fshehtë','Access Key ID'=>'ID Kyçi Hyrjeje','Recommended Mailers'=>'Postues të Rekomanduar','Save and Continue'=>'Ruajeni dhe Vazhdoni','Choose Your SMTP Mailer'=>'Zgjidhni Postuesin Tuaj SMTP','is a PRO Feature'=>'është një Veçori PRO','Choose a Different Mailer'=>'Zgjidhni një Postues Tjetër','I Understand, Continue'=>'E kuptoj, Vazhdo','Read how to set up the Gmail mailer'=>'Lexoni si të ujdiset postuesi Gmail','Select which email address you would like to send your emails from.'=>'Përzgjidhni nga cila adresë email do të donit të dërgohen email-e tuaj.','Authorized Redirect URI'=>'URI Ridrejtimesh të Autorizuara','Application Password'=>'Fjalëkalim Aplikacioni','Application ID'=>'ID Aplikacioni','Read how to set up Mailgun'=>'Lexoni si të ujdiset Mailgun-i','Define which endpoint you want to use for sending messages. If you are operating under EU laws, you may be required to use EU region. %1$sMore information%2$s on Mailgun.com.'=>'Përcaktoni cilin pikëmbarim doni të përdoret për dërgim mesazhesh. Nëse vepronin nën ligjet e BE-së, mund t’ju duhet të përdorni zonën e BE-së. %1$sMë tepër të dhëna%2$s te Mailgun.com.','%1$sFollow this link%2$s to get a Domain Name from Mailgun.'=>'%1$sNdiqni këtë lidhje%2$s që të merrni një Emër Përkatësie nga Mailgun-i.','%1$sFollow this link%2$s to get an API Key for Brevo.'=>'%1$sNdiqni këtë lidhje%2$s që të merrni një Kyç APi për Brevo-n.','Read how to set up Zoho Mail'=>'Lexoni si të ujdiset Zoho Mail','Redirect URI'=>'URI Ridrejtimi','The data center location used by your Zoho account.'=>'Vendndodhja e qendrës së të dhënave e përdorur nga llogaria juaj Zoho.','Read how to set up Sendinblue'=>'Lexoni si të ujdiset Sendinblue','Get Started with Sendinblue'=>'Fillojani Punës me Sendinblue','%1$sFollow this link%2$s to get an API Key for Sendinblue.'=>'%1$sNdiqni këtë lidhje%2$s që të merrni një Kyç APi për Sendinblue.','Read how to set up SMTP.com'=>'Lexoni si të ujdiset SMTP.com','If enabled, the From Email setting above will be used for all emails, ignoring values set by other plugins.'=>'Nëse i vihet shenjë, rregullimi “Email Prej” më sipër do të përdoret për krejt email-et, duke shpërfillur vlera të caktuara nga shtojca të tjera.','If enabled, the From Name setting above will be used for all emails, ignoring values set by other plugins.'=>'Nëse i vihet shenjë, rregullimi “Emër Prej” më sipër do të përdoret për krejt email-et, duke shpërfillur vlera të caktuara nga shtojca të tjera.','%1$sFollow this link%2$s to get a Sender Name for SMTP.com.'=>'Që të merrni një Emër Dërguesi nga SMTP.com, %1$sndiqni këtë lidhje%2$s.','%1$sFollow this link%2$s to get an API Key for SMTP.com.'=>'Që të merrni një kyç APi për SMTP.com, %1$sndiqni këtë lidhje%2$s.','Finish Setup'=>'Përfundoje Ujdisjen','Send us Feedback'=>'Dërgonani Përshtypjet','Start Troubleshooting'=>'Nis Diagnostikimin','We just tried to send a test email, but something prevented that from working. To see more details about the issue we detected, as well as our suggestions to fix it, please start troubleshooting.'=>'Sapo provuam të dërgojmë një email prove, por diçka e pengoi funksionimin e kësaj. Që të shihni më tepër hollësi rreth problemit që pikasëm, si dhe sugjerimet tona se si të ndreqet, ju lutemi, filloni diagnostikimin.','Whoops, looks like things aren’t configured properly.'=>'Oh, duket sikur gjërat s’janë formësuar si duhet.','WP SMTP'=>'WP SMTP','SMTP Mailer'=>'Postues SMTP','Post SMTP Mailer'=>'Post SMTP Mailer','Easy WP SMTP'=>'Easy WP SMTP','Previous Step'=>'Hapi i Mëparshëm','Skip this Step'=>'Anashkalojeni këtë Hap','Import Data and Continue'=>'Importo të Dhëna dhe Vazhdo','We have detected other SMTP plugins installed on your website. Select which plugin\'s data you would like to import to WP Mail SMTP.'=>'Kemi pikasur të tjera shtojca SMTP të instaluara në sajtin tuaj. Përzgjidhni të dhënat e cilës shtojce do të donit të importohen te WP Mail SMTP.','Import data from your current plugins'=>'Importoni të dhëna prej shtojcave tuaja të tanishme','Close and exit the Setup Wizard'=>'Mbylle dhe dil nga Ndihmësi i Ujdisjes','Let\'s Get Started'=>'Le T’ia Fillojmë','We’ll guide you through each step needed to get WP Mail SMTP fully set up on your site.'=>'Do t’ju udhëheqim përmes çdo hapi të nevojshëm për ta pasur WP Mail SMTP-në plotësisht të ujdisur në sajtin tuaj.','Welcome to the WP Mail SMTP Setup Wizard!'=>'Mirë se vini te Ndihmësi i Ujdisjes së WP Mail SMTP!','It looks like something went wrong...'=>'Duket se diç shkoi ters…','Whoops, we found an issue!'=>'Oh, gjetëm një problem!','Return to Mailer Settings'=>'Kthehu te Rregullimet e Postuesit','Could Not Save Changes'=>'S’u Ruajtën Dot Ndryshimet','Settings Updated'=>'U përditësuan Rregullimet','WP Mail SMTP has detected that your site is running an outdated version of WordPress (%s). WP Mail SMTP requires at least WordPress version 4.9.'=>'WP Mail SMTP ka pikasur se sajti juaj po xhiron me një version të vjetruar të WordPress-it (%s). WP Mail SMTP lyp të paktën WordPress version 4.9.','Yikes! WordPress Update Required'=>'Uuuf! Lypset Përditësim WordPress-i','WP Mail SMTP has detected that your site is running an outdated, insecure version of PHP (%1$s). Some mailers require at least PHP version 5.6. Updating to the recommended version (PHP %2$s) only takes a few minutes and will make your website significantly faster and more secure.'=>'WP Mail SMTP ka pikasur se sajti juaj xhiron me një version të vjetruar, të pasigurt, të PHP-së (%1$s). Disa postues kërkojnë doemos të paktën PHP version 5.6. Përditësimi me versionin e rekomanduar (PHP %2$s) ha vetëm pak minuta dhe do ta bëjë sajtin tuaj shumë më të shpejtë dhe më të sigurt.','Yikes! PHP Update Required'=>'Uuuf! Lypset Përditësim i PHP-së','WP Mail SMTP has detected that your site is running an outdated, insecure version of PHP (%1$s), which could be putting your site at risk for being hacked. WordPress stopped supporting your PHP version in April, 2019. Updating to the recommended version (PHP %2$s) only takes a few minutes and will make your website significantly faster and more secure.'=>'WP Mail SMTP-ja ka pikasur se sajti juaj xhiron me një version të vjetruar, të pasigurt, të PHP-së (%1$s), çka do ta vinte sajtin tuaj në rrezik nga hyrje të paautorizuara në të. WordPress-i reshti së mbuluari versionin tuaj të PHP-së në prill të 2019-s. Përditësimi me versionin e rekomanduar (PHP %2$s) ha vetëm pak minuta dhe do ta bëjë sajti tuaj shumë më të shpejtë dhe më të sigurt.','Something went wrong. Please try again later.'=>'Diç shkoi ters. Ju lutemi, riprovoni më vonë.','Upgrade functionality not available!'=>'Mungon funksioni i përmirësimit!','Please enter a valid license key!'=>'Ju lutemi, jepni një kyç të vlefshëm licence!','You don\'t have the permission to perform this action.'=>'S’keni leje për të kryer këtë veprim.','You are already using the WP Mail SMTP PRO version. Please refresh this page and verify your license key.'=>'Po e përdorni tashmë versionin Pro të WP Mail SMTP-së. Ju lutemi, rifreskoni këtë faqe dhe verifikoni kyçin tuaj të licencës.','WP Call Button'=>'WP Call Button','SeedProd Landing Page Builder'=>'Ndërtues SeedProd Faqeje Hyrëse','Smash Balloon Social Photo Feed'=>'Smash Balloon Social Photo Feed','Giveaways by RafflePress'=>'Gjëra falas nga RafflePress','All in One SEO'=>'All in One SEO','Google Analytics by MonsterInsights'=>'Google Analytics nga MonsterInsights','Could not install the plugin. WP Plugin installer could not retrieve plugin information.'=>'S’u instalua dot shtojca. Instaluesi WP i shtojcave s’mori dot informacionin mbi shtojcën.','Could not install the plugin. WP Plugin installer initialization failed.'=>'S’u instalua dot shtojca. Gatitja e instaluesit WP të shtojcave dështoi.','Could not install the plugin. Don\'t have file permission.'=>'S’u instalua dot shtojca. S’keni leje mbi kartelë.','Could not install the plugin. Plugin slug is missing.'=>'S’u instalua dot shtojca. Mungon identifikuesi i shtojcës.','Could not install the plugin. You don\'t have permission to install plugins.'=>'S’u instalua dot shtojca. S’keni leje të instaloni shtojca.','You don\'t have permission to change options for this WP site!'=>'S’keni leje të ndryshoni mundësitë për këtë sajt WP!','Contact Us'=>'Lidhuni Me Ne','Copy the error message above and paste it in a message to the WP Mail SMTP support team.'=>'Kopjoni mesazhin e gabimit më sipër dhe hidheni te një mesazh për ekipin e asistencës së WP Mail SMTP-së.','If you\'ve checked each of these details and are still running into issues, then please get in touch with our support team. We’d be happy to help!'=>'Nëse e kontrolluat secilën prej këtyre hollësive dhe ende keni probleme, atëherë, ju lutemi, lidhuni me ekipin tonë të asistencës. Do të jemi të lumtur t’ju ndihmojmë!','Confirm that your browser is updated to the latest version.'=>'Ripohoni se shfletuesi juaj është përditësuar me versionin më të ri.','If you aren\'t already using Chrome, Firefox, Safari, or Edge, then please try switching to one of these popular browsers.'=>'Nëse s’përdorni tashmë Chrome, Firefox, Safari, ose Edge, atëherë ju lutemi, provoni të kaloni në një nga këta shfletues popullorë.','If you are using an ad blocker, please disable it or whitelist the current page.'=>'Nëse përdorni një bllokues reklamash, ju lutemi, çaktivizojeni ose kalojeni faqen e tanishme te lista e të lejuarave.','In order to fix this issue, please check each of the items below:'=>'Që të mund të ndreqet ky problem, ju lutemi, kontrolloni secilin nga zërat më poshtë:','It looks like something is preventing JavaScript from loading on your website. WP Mail SMTP requires JavaScript in order to give you the best possible experience.'=>'Duket sikur diçka e pengon JavaScript-in të ngarkohet në sajtin tuaj. WP Mail SMTP-ja lyp JavaScript që të mund t’ju japë punimin më të mirë.','Whoops, something\'s not working.'=>'Hëm, diçka s’po funksionon.','WP Mail SMTP logo'=>'Stemë e WP Mail SMTP','Go back to the Dashboard'=>'Kthehuni te Pulti','WP Mail SMTP &rsaquo; Setup Wizard'=>'WP Mail SMTP &rsaquo; Ndihmës Ujdisjeje','<strong>Bonus:</strong> WP Mail SMTP users get <span class="highlight">%s off</span> regular price,<br>applied at checkout.'=>'<strong>Bonus:</strong> Përdoruesit e WP Mail SMTP përfitojnë <span class="highlight">%s ulje</span> të çmimit të rregullt,<br>e aplikuar gjatë përfundimit të blerjes.','We\'re sorry, the %mailer% mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Na ndjeni, postuesi %mailer% s’është pjesë e planit tuaj. Ju lutemi, përmirësojeni me planin PRO që të çlirohen krejt këto veçori të mahnitshme.','Setup Wizard'=>'Ndihmës Ujdisjesh','%s icon'=>'ikonë %s','Domain Check Results'=>'Përfundime Kontrolli Përkatësie','The test email might have sent, but its deliverability should be improved.'=>'Email-i provë mund të jetë dërguar, por shkalla e dërgimit të tij duhet përmirësuar.','If updating the API Key doesn\'t resolve this issue, please contact our support.'=>'Nëse përditësimi i kyçi API nuk e zgjidh këtë problem. ju lutemi, lidhuni me asistecën tonë.','Save the plugin settings.'=>'Ruaji rregullimet e shtojcës.','Make sure your API Key in the SendGrid mailer settings is correct and valid.'=>'Sigurohuni se kyçi juaj API te rregullimet për postuesin SendGrid është i saktë dhe i vlefshëm.','It looks like your SendGrid API Key is invalid.'=>'Duket sikur kyçi juaj API për SendGrud është i pavlefshëm.','Invalid SendGrid API key'=>'Kyçi API SendGrid i pavlefshëm','Multisite Support - network settings for easy management'=>'Asistencë për Shumësajtësh - rregullime rrjeti për administrim të kollajtë','Connect'=>'Lidhu','Paste license key here'=>'Hidhni këtu kyçin e licencës','Already purchased? Simply enter your license key below to connect with WP Mail SMTP Pro!'=>'I blerë tashmë? Thjesht jepni kyçin tuaj të licencës më poshtë që të lidhet me WP Mail SMTP Pro!','Pro version installed but needs to be activated on the Plugins page.'=>'Versioni Pro u instalua, por lypset të aktivizohet te faqja e Shtojcave.','There was an error while installing an upgrade. Please try again.'=>'Pati një gabim teksa instalohej një përmirësim. Ju lutemi, riprovoni.','There was an error while installing an upgrade. Please check file system permissions and try again. Also, you can download the plugin from wpmailsmtp.com and install it manually.'=>'Pati një gabim teksa instalohej një përmirësim. Ju lutemi, kontrolloni lejet mbi sistemin e kartelave dhe riprovoni. Veç kësaj, mund të shkarkoni shtojcën nga wpmailsmtp.com dhe ta instaloni dorazi.','There was an error while installing an upgrade. Please download the plugin from wpmailsmtp.com and install it manually.'=>'Pati një gabim teksa instalohej një përmirësim. Ju lutemi, shkarkojeni shtojcën nga wpmailsmtp.com dhe instalojeni dorazi.','There was an error while generating an upgrade URL. Please try again.'=>'Pati një gabim teksa prodhohej një URL përmirësimi. Ju lutemi, riprovoni.','WP Mail SMTP Pro was already installed, but was not active. We activated it for you.'=>'WP Mail SMTP Pro qe instaluar tashmë, por s’është aktiv. E aktivizuan ne për ju.','Only the Lite version can be upgraded.'=>'Mund të përmirësohet vetëm versioni Lite.','Please enter your license key to connect.'=>'Ju lutemi, që të lidhet, jepni kyçin tuaj të licencës.','You are not allowed to install plugins.'=>'S’keni leje të instaloni shtojca.','Unfortunately there was a server connection error.'=>'Mjerisht pati një gabim lidhjeje me shërbyesin.','OK'=>'OK','Oops!'=>'Hëm!','Almost Done'=>'Pothuajse Mbaruat','Please input the sending domain/subdomain you configured in your Brevo (formerly Sendinblue) dashboard. More information can be found in our <a href="%s" target="_blank" rel="noopener noreferrer">Brevo documentation</a>.'=>'Ju lutemi, jepni përkatësinë/nënpërkatësinë e dërgimit që keni formësuar te pulti juaj në Brevo (ish-Sendinblue). Më tepër hollësi mund të gjenden te <a href="%s" target="_blank" rel="noopener noreferrer">dokumentimi ynë për Brevo</a>.','Please input the sending domain/subdomain you configured in your SendGrid dashboard. More information can be found in our <a href="%s" target="_blank" rel="noopener noreferrer">SendGrid documentation</a>.'=>'Ju lutemi, jepni përkatësinë/nënpërkatësinë e dërgimit që keni formësuar te pulti juaj në SendGrid. Më tepër hollësi mund të gjenden te <a href="%s" target="_blank" rel="noopener noreferrer">dokumentimi ynë për SendGrid</a>.','Sending Domain'=>'Përkatësi Dërgimi','Please make sure your Google Client ID and Secret in the plugin settings are valid. Save the settings and try the Authorization again.'=>'Ju lutemi, sigurohuni se ID-ja dhe E fshehta Klienti Google te rregullimet e shtojcës janë të vlefshëm. Ruajini rregullimet dhe riprovoni Autorizimin.','The email message ID is missing.'=>'Mungon ID-ja e mesazhit të email-t.','The response object is invalid (missing getId method).'=>'Objekti përgjigje është i pavlefshëm (mungon metoda <em>getId</em>).','The password is encrypted in the database, but for improved security we recommend using your site\'s WordPress configuration file to set your password.'=>'Fjalëkalimi fshehtëzohet në bazën e të dhënave, por për më tepër siguri, rekomandojmë përdorimin e kartelës së formësimit WordPress të sajtit tuaj për të caktuar fjalëkalimin tuaj.','If enabled, these global settings will manage email sending for all subsites of this multisite.'=>'Në u aktivizoftë, këto rregullime globale do të administrojnë dërgimin për krejt nënsajtet e këtij shumësajtëshi.','If disabled, each subsite of this multisite will have its own WP Mail SMTP settings page that has to be configured separately.'=>'Në u çaktivizoftë, çdo nënsajt i këtij shumësajtëshi do të ketë faqen e vet të rregullimeve WP Mail SMTP që duhet formësuar më vete.','Make the plugin settings global network-wide'=>'Bëji globale për krejt rrjetin rregullimet e shtojcës','Settings control'=>'Kontroll rregullimesh','Simply enable network-wide settings and every site on your network will inherit the same SMTP settings. Save time and only configure your SMTP provider once.'=>'Thjesht aktivizoni rregullimet për krejt rrjetin dhe çdo sajt në rrjetin tuaj do të trashëgojë të njëjtat rregullime për SMTP-në. Kurseni kohë dhe formësoni vetëm një herë furnizuesin tuaj të SMTP-së.','Pro+ badge icon'=>'Ikonë steme Pro+','Multisite'=>'Shumësajtësh','Loading'=>'Po ngarkohet','Optionally configure settings at the network level or manage separately for each subsite'=>'Formësojini rregullimet, në daçi, në shkallë rrjeti ose administrojini veçmas për çdo nënsajt','All Global Network Settings'=>'Krejt Rregullimet Globale të Rrjetit','No Global Network Settings'=>'Pa Rregullime Globale Rrjeti','Microsoft Outlook (with Office365 support), Amazon SES and Zoho Mail'=>'Microsoft Outlook (me mbulim për Office365), Amazon SES dhe Zoho Mail','Additional Mailer Options'=>'Mundësi Shtesë Postuesi','Access is limited to standard mailer options only'=>'Hyrja është kufizuar vetëm në mundësi standarde postuesi','Limited Mailers'=>'Postues të Kufizuar','Access to all Email Logging options right inside WordPress'=>'Hyrje te krejt mundësitë për Regjistrime Email-i drejt e brenda WordPress-it','WordPress Multisite'=>'WordPress Multisite','Mailer Options'=>'Mundësi Postuesi','None selected'=>'S’u përzgjodh ndonjë','M j, Y @ g:ia'=>'j M, Y @ g:ia','Lite install date'=>'Datë e instalimit të versionit Lite','We\'re sorry, the Zoho Mail mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Na ndjeni, postuesi Zoho Mail s’është pjesë e planit tuaj. Ju lutemi, përmirësojeni me planin PRO që të çlirohen krejt këto veçori të mahnitshme.','Zoho Mail'=>'Zoho Mail','By allowing us to track usage data we can better help you because we know with which WordPress configurations, themes and plugins we should test.'=>'Duke na lejuar ndjekjen e të dhënave të përdorimit, mund t’ju ndihmojmë më mirë, ngaqë do të dimë se me cilët formësime të WordPress-it, tema dhe shtojca do të duhet të bëjmë testime.','Allow Usage Tracking'=>'Lejo Ndjekje Përdorimi','Dismiss this message.'=>'Hidhe tej këtë mesazh.','You’re using WP Mail SMTP Lite. To unlock more features, consider <a href="%s" target="_blank" rel="noopener noreferrer">upgrading to Pro</a>.'=>'Po përdorni WP Mail SMTP Lite. Për të shkyçur më tepër veçori, shihni mundësinë e <a href="%s" target="_blank" rel="noopener noreferrer">përmirësimit me versionin Pro</a>.','Next message'=>'Mesazhi pasues','Previous message'=>'Mesazhi i mëparshëm','Dismiss this message'=>'Hidhe tej këtë mesazh','Plugin icon'=>'Ikonë shtojce','Missing table: %s'=>'Tabelë që mungon: %s' . "\0" . 'Tabela që mungojnë: %s','WP Mail SMTP DB tables check has failed'=>'Kontrolli i tabelave WP Mail SMTP DB dështoi','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it looks like they exist in your database.'=>'Për disa nga veçoritë e tij, WP Mail SMTP po përdor tabela vetjake baze të dhënash. Që të mund të funksionojë si duhet, tabelat vetjake duhen krijuar, dhe duket se gjenden në bazën tuaj të të dhënave.','WP Mail SMTP DB tables are created'=>'Tabelat e bazës së të dhënave për WP Mail SMTP janë krijuar','No DB tables found.'=>'S’u gjetën tabela DB.','DB tables'=>'Tabela DB','Do WP Mail SMTP DB tables exist?'=>'A ekzistojnë tabela WP Mail SMTP DB?','If you want to use a different From Email address you can set up a Google email alias. <a href="%s" target="_blank" rel="noopener noreferrer">Follow these instructions</a> and then select the From Email at the top of this page.'=>'Nëse doni të përdorni një tjetër adresë për Email Nga, mund të ujdisni një alias email-i Google. <a href="%s" target="_blank" rel="noopener noreferrer">Ndiqni këto udhëzime</a> dhe mandej përzgjidhni Email Nga në krye të kësaj faqeje.','Error'=>'Gabim','General error'=>'Gabim i përgjithshëm','There was an error while upgrading the database. Please contact %1$s support with this information: %2$s.'=>'Pati një gabim teksa përmirësohej baza e të dhënave. Ju lutemi, lidhuni me asistencën e %1$s me këto hollësi: %2$s.','Warning icon'=>'Ikonë sinjalizimesh','Cancel'=>'Anuloje','<p>The Default (PHP) mailer is currently selected, but is not recommended because in most cases it does not resolve email delivery issues.</p><p>Please consider selecting and configuring one of the other mailers.</p>'=>'<p>Aktualisht është i përzgjedhur postuesi parazgjedhje (PHP), por kjo s’është e rekomanduar, ngaqë në shumicën e rasteve nuk zgjidh probleme të dërgimit të email-eve.</p><p>Ju lutemi, shihni mundësinë e përzgjedhjes dhe formësimit të njërit prej postuesve të tjerë.</p>','Heads up!'=>'Hapni sytë!','I already did'=>'E bëra tashmë','No, maybe later'=>'Ncuq, ndoshta më vonë','No thanks'=>'Jo, faleminderit','We\'re sorry to hear you aren\'t enjoying WP Mail SMTP. We would love a chance to improve. Could you take a minute and let us know what we can do better?'=>'Na vjen keq që nuk po ju shijon WP Mail SMTP. Do të donim një shans për ta përmirësuar. A mund të ndaleni një minutë dhe të na bëni të ditur se ç’mund të bëjmë më mirë?','Yes'=>'Po','Are you enjoying WP Mail SMTP?'=>'A po ju pëlqen WP Mail SMTP?','For a quick fix, until your web hosting resolves this, you can downgrade to PHP version 7.3 on your server.'=>'Për një ndreqje të shpejtë, derisa strehuesi ynë web të zgjidhë këtë, mund të ktheheni te versioni PHP 7.3 në shërbyesin tuaj.','They should be able to resolve this issue for you.'=>'Ata duhet të jenë në gjendje të zgjidhni këtë problem për ju.','Contact your web hosting provider and inform them you are having issues with libpcre2 library on PHP 7.4.'=>'Lidhuni me shërbyesin tuaj web dhe bëjuni të ditur që keni probleme me librarinë libpcre2 në PHP 7.4.','There is a known issue with PHP version 7.4.x, when using libpcre2 library version lower than 10.33.'=>'Ka një problem të ditur me versionin PHP 7.4.x, kur përdoret libraria libpcre2 në version më të ulët se 10.33.','It looks like your server is running PHP version 7.4.x with an outdated PCRE library (libpcre2) that has a known issue with email address validation.'=>'Duket sikur shërbyesi juaj xhiron PHP version 7.4.x me një librari PCRE të vjetruar (libpcre2) që ka një problem të ditur me vlerësim adresash email.','PCRE library issue'=>'Problem librarie PCRE','If you don\'t know how to do the above we strongly suggest contacting your hosting support and provide them the "full Error Log for debugging" below and these steps. They should be able to fix this issue for you.'=>'Nëse s’dini si ta bëni sa më sipër, sugjerojmë me forcë të lidheni me asistencën e strehimit tuaj dhe t’u jepni "Regjistrin e plotë të Gabimeve për diagnostikim" më poshtë dhe këta hapa. Duhet të jenë në gjendje të ndreqin këtë problem për ju.','(If cURL can\'t be enabled on your hosting server) Enable PHP setting: allow_url_fopen, by adding "allow_url_fopen = On" to the php.ini file (without the quotation marks)'=>'(Nëse në shërbyesin tuaj cURL s’mund të aktivizohet) Aktivizoni rregullimin PHP: allow_url_fopen, duke shtuar "allow_url_fopen = On" te kartela php.ini (pa thonjëzat)','(Recommended) Enable PHP extension: cURL, by adding "extension=curl" to the php.ini file (without the quotation marks) OR'=>'(E rekomanduar) Aktivizoni zgjerimin PHP: cURL, duke shtuar "extension=curl" te kartela php.ini (pa thonjëzat) OSE','Edit your php.ini file on your hosting server.'=>'Përpunoni kartelën tuaj php.ini te shërbyesi juaj i strehimit.','GuzzleHttp requires cURL, the allow_url_fopen ini setting, or a custom HTTP handler.'=>'GuzzleHttp lyp cURL, rregullimin allow_url_fopen në ini, ose një trajtues të përshtatur HTTP-je.','GuzzleHttp requirements.'=>'Domosdoshmëri të GuzzleHttp-së.','Please make sure you entered an accurate Sender Name in WP Mail SMTP plugin settings.'=>'Ju lutemi, sigurohuni se keni dhënë një Emër të saktë Dërguesi te rregullimet e shtojcës WP Mail SMTP.','Your Sender Name option is incorrect.'=>'Mundësia juaj Emër Dërguesi është e pasaktë.','SMTP.com API Error.'=>'Gabim API SMTP.com.','Contact your hosting support, show them the "full Error Log for debugging" below and share this <a href="%s" target="_blank" rel="noopener noreferrer">link</a> with them.'=>'Lidhuni me asistencën e strehuesit tuaj, u tregoni "Regjistrin e plotë të Gabimeve për diagnostikim" më poshtë dhe tok me to jepuni edhe këtë <a href="%s" target="_blank" rel="noopener noreferrer">lidhje</a>.','Verify that the host\'s SSL certificate is valid.'=>'Verifikoni që dëshmia SSL e strehës është e vlefshme.','There are a few reasons why this is happening. It could be that the host certificate is misconfigured, or this server\'s OpenSSL is using an outdated CA bundle.'=>'Ka ca arsye pse ndodh kjo. Mund të jetë ngaqë dëshmia e strehës është keqformësuar, oser OpenSSL në këtë shërbyes përdor një paketë AD të vjetruar.','This means OpenSSL on your server isn\'t able to verify the host certificate.'=>'Kjo do të thotë se OpenSSL në shërbyesin tuaj s’është në gjendje të verifikojë dëshminë e strehës.','Misconfigured server certificate.'=>'Dëshmi shërbyesi e keqformësuar.','Please read this <a href="%s" target="_blank" rel="noopener noreferrer">support article</a> if you want to enable this option using constants.'=>'Nëse doni të aktivizoni këtë mundësi duke përdorur konstante, ju lutemi, lexoni këtë <a href="%s" target="_blank" rel="noopener noreferrer">artikull asistence</a>.','Then click the “Allow plugin to send emails using your Google account” button and re-enable access.'=>'Mandej klikoni mbi butonin “Lejojeni shtojcën të dërgojë email duke përdorur llogarinë tuaj Google” dhe riaktivizoni përdorimin.','Go to WP Mail SMTP plugin settings page. Click the “Remove OAuth Connection” button.'=>'Kaloni te faqja e rregullimeve të shtojcës WP Mail SMTP. Klikoni mbi butonin “Hiqe Lidhjen OAuth”.','Please re-grant Google app permissions!'=>'Ju lutemi, riakordoni leje aplikacioni Google!','If you\'d prefer not to set up SSL, or need an SMTP solution in the meantime, please select a different mailer option.'=>'Nëse do të parapëlqenit të mos ujdisnit SSL, ose ndërkohë ju duhet një zgjidhje SMTP, ju lutemi, përzgjidhni një tjetër mundësi postuesi.','%s requires an SSL certificate, and so is not currently compatible with your site. Please contact your host to request a SSL certificate, or check out <a href="https://www.wpbeginner.com/wp-tutorials/how-to-add-ssl-and-https-in-wordpress/" target="_blank">WPBeginner\'s tutorial on how to set up SSL</a>.'=>'%s lyp një dëshmi SSL, dhe ndaj aktualisht s’është i përputhshëm me sajtin tuaj. Ju lutemi, lidhuni me strehuesin tuaj për t’i kërkuar një dëshmi SSL, ose shihni <a href="https://www.wpbeginner.com/wp-tutorials/how-to-add-ssl-and-https-in-wordpress/" target="_blank">përkujdesoren nga WPBeginner se si të ujdiset SSL-ja</a>.','Learn More'=>'Mësoni Më Tepër','Get Started with Pepipost'=>'Nisjani me Pepipost-in','Get Sender Name'=>'Merrni Emrin e Dërguesit','Follow this link to get a Sender Name from SMTP.com: %s.'=>'Ndiqni këtë lidhje që të merrni Emër Dërguesi prej SMTP.com-it: %s.','Sender Name'=>'Emër Dërguesi','Get API Key'=>'Merrni Kyç API','Follow this link to get an API Key from SMTP.com: %s.'=>'Ndiqni këtë lidhje që të merrni një Kyç API prej SMTP.com-i: %s.','SMTP.com'=>'SMTP.com','Get Started with SMTP.com'=>'Fillojani me SMTP.com-in','Channel:'=>'Kanal:','Api Key:'=>'Kyç API:','Go to WP Mail SMTP Settings page'=>'Kaloni te faqja e Rregullimeve për WP Mail SMTP','Don\'t see what you\'re looking for?'=>'S’po gjeni dot ç’po kërkoni?','Configure mailer'=>'Formësoni postuesin','The WP Mail SMTP plugin mailer setup is incomplete. Please click on the link below to access plugin settings and configure the mailer.'=>'Ujdisja e postuesit WP Mail SMTP u plotësua. Ju lutemi, klikoni mbi lidhjen më poshtë që të hyni te rregullimet e shtojcës dhe të formësoni postuesin.','WP Mail SMTP mailer setup is incomplete'=>'Ujdisja e postuesit WP Mail SMTP u plotësua','You currently have the default mailer selected, which means that you haven’t set up SMTP yet.'=>'Hëpërhë keni të përzgjedhur postuesin parazgjedhje, që do të thotë se nuk e keni ujdisur ende SMTP-në.','Test email sending'=>'Provoni dërgimin e email-it','The WP Mail SMTP plugin mailer setup is complete. You can send a test email, to make sure it\'s working properly.'=>'Ujdisja e postuesit WP Mail SMTP u plotësua. Mund të dërgoni një email provë, për t’u siguruar se funksionon si duhet.','WP Mail SMTP mailer setup is complete'=>'Ujdisja e postuesit WP Mail SMTP u plotësua','Current mailer'=>'Postuesi i tanishëm','No debug notices found.'=>'S’u gjetën njoftime diagnostikimi.','Debug'=>'Diagnostikojeni','License key type'=>'Lloj kyçi licence','Is WP Mail SMTP mailer setup complete?'=>'A është e plotësuar ujdisja e postuesit WP Mail SMTP?','Changes that you made to the settings are not saved!'=>'Ndryshimet që bëtë te rregullimet s’janë ruajtur!','RafflePress Pro'=>'RafflePress Pro','RafflePress'=>'RafflePress','WP Mail SMTP is brought to you by the same team that\'s behind the most user friendly WordPress forms, <a href="%1$s" target="_blank" rel="noopener noreferrer">WPForms</a>, the largest WordPress resource site, <a href="%2$s" target="_blank" rel="noopener noreferrer">WPBeginner</a>, the most popular lead-generation software, <a href="%3$s" target="_blank" rel="noopener noreferrer">OptinMonster</a>, the best WordPress analytics plugin, <a href="%4$s" target="_blank" rel="noopener noreferrer">MonsterInsights</a>, and <a href="%5$s" target="_blank" rel="noopener noreferrer">more</a>.'=>'WP Mail SMTP ju vjen nga i njëjti ekip që gjendet pas formularëve WordPress më të kollajshëm për përdoruesin, <a href="%1$s" target="_blank" rel="noopener noreferrer">WPForms</a>, sajtin më të madh të burimeve për WordPress, <a href="%2$s" target="_blank" rel="noopener noreferrer">WPBeginner</a>, software-in më popullor për <em>lead-generation</em>, <a href="%3$s" target="_blank" rel="noopener noreferrer">OptinMonster</a>, shtojcën më të mirë WordPress për analiza, <a href="%4$s" target="_blank" rel="noopener noreferrer">MonsterInsights</a>, dhe <a href="%5$s" target="_blank" rel="noopener noreferrer">të tjera</a>.','Suggest a Mailer'=>'Sugjeroni një Postues','Pepipost SMTP'=>'Pepipost SMTP','Get the API Key'=>'Merrni kyç API','Read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Pepipost documentation</a> to learn how to configure Pepipost and improve your email deliverability.'=>'Lexoni <a href="%2$s" target="_blank" rel="noopener noreferrer">dokumentimin tonë për Pepipost-in</a> Që të mësoni si ta formësoni Pepipost-in dhe përmirësoni shkallën e dërgimit të email-eve tuaj.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Pepipost</a> is a transactional email service. Every month Pepipost delivers over 8 billion emails from 20,000+ customers. Their mission is to reliably send emails in the most efficient way and at the most disruptive pricing ever. Pepipost provides users 30,000 free emails the first 30 days.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Pepipost</a> është një shërbim transaksionesh email-esh i rekomanduar. Pepipost-i dërgon mbi 8 miliardë email-e nga më shumë se 20 mijë klientë. Misioni i tyre është të dërgimi i email-eve në mënyrë të qëndrueshme dhe në rrugën më efikase dhe me çmimet më mahnitëse se kurrë.  Pepipost u furnizon përdoruesve 30 mijë email-e falas 30 ditët e para.','Download'=>'Shkarkim','To send emails, go to plugin <a href="%s">Misc settings</a> and disable the "Do Not Send" option.'=>'Që të dërgoni email-e, shkoni te <a href="%s">Rregullime të ndryshme</a>të shtojcës dhe çaktivizoni mundësinë "Mos Dërgo".','To send emails, change the value of the %1$s constant to %2$s.'=>'Që të dërgoni email-e, ndryshoni vlerën e konstantes %1$s në %2$s.','<strong>EMAILING DISABLED:</strong> The %s is currently blocking all emails from being sent.'=>'<strong>DËRGIM EMAIL-ESH I ÇAKTIVIZUAR:</strong> %s po bllokon dërgimin e krejt email-eve.','We\'re sorry, the Amazon SES mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Na ndjeni, postuesi Amazon SES s’është pjesë e planit tuaj. Ju lutemi, përmirësojeni me planin PRO që të çlirohen krejt këto veçori të mahnitshme.','Amazon SES'=>'Amazon SES','We\'re sorry, the Microsoft Outlook mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Na ndjeni, postuesi Microsoft Outlook s’është pjesë e planit tuaj. Ju lutemi, përmirësojeni me planin PRO që të çlirohen krejt këto veçori të mahnitshme.','Already purchased?'=>'E blerë tashmë?','<strong>Bonus:</strong> WP Mail SMTP users get <span>%s off</span> regular price,<br>applied at checkout.'=>'<strong>Bonus:</strong> Përdoruesit e WP Mail SMTP përfitojnë <span>
%s ulje</span> të çmimit të rregullt,<br>e aplikuar gjatë përfundimit të blerjes.','Upgrade to Pro'=>'Përmirësojeni me versionin Pro','%name% is a PRO Feature'=>'%name% është një Veçori PRO','Educational notice for this mailer was successfully dismissed.'=>'Njoftimi edukativ për këtë postues u hodh tej me sukses.','<strong>This is not recommended</strong> and should only be done for staging or development sites.'=>'<strong>Kjo s’është e këshillueshme</strong> dhe duhet kryer vetëm për sajte provë ose zhvillimi.','Email Delivery Errors were disabled using a %s filter.'=>'Gabime Dërgimi Emaile-sh qenë çaktivizuar duke përdorur një filtër %s.','Hide Email Delivery Errors'=>'Fshihi Gabimet e Dërgimit të Email-eve','Get v3 API Key'=>'Merrni Kyç API v3','Follow this link to get an API Key: %s.'=>'Ndiqni këtë lidhje që të merrni një Kyç API: %s.','The Gmail mailer works well for sites that send low numbers of emails. However, Gmail\'s API has rate limitations and a number of additional restrictions that can lead to challenges during setup.<br><br>If you expect to send a high volume of emails, or if you find that your web host is not compatible with the Gmail API restrictions, then we recommend considering a different mailer option.'=>'Postuesi Gmail punon mirë për sajte që dërgojnë numër të vogël email-esh. Por, API i Gmail-it ka kufizime sasie dhe një numër kufizimesh shtesë që mund të shpien në probleme gjatë ujdisjes. <br><br>Nëse prisni të dërgoni një vëllim të madh email-esh, ose nëse shihni se streha juaj web s’është e përputhshme me kufizimet e API-t Gmail, atëherë këshillojmë të shihni mundësinë e përdorimit të një postuesi tjetër.','Meanwhile you can switch to some other mailers.'=>'Ndërkohë, mund të kaloni te ca postues të tjerë.','https://wpmailsmtp.com/'=>'https://wpmailsmtp.com/','There was an error while processing the Google authentication request. Please make sure that you have Client ID and Client Secret both valid and saved.'=>'Pati një gabim teksa përpunohej kërkesa e mirëfilltësimit me Google. Ju lutemi, sigurohuni se janë të vlefshme dhe keni ruajtur si ID Klienti, ashtu edhe të Fshehtë Klienti.','You have successfully linked the current site with your Google API project. Now you can start sending emails through Gmail.'=>'E keni lidhur me sukses sajtin e tanishëm me projektin tuaj API Google. Tani mund të filloni të dërgoni email-e përmes Gmail-it.','Activate'=>'Aktivizoje','<strong>WP Mail SMTP plugin is disabled</strong> on your site until you fix the issue. <a href="%s" target="_blank" rel="noopener noreferrer">Read more for additional information.</a>'=>'<strong>Shtojca WP Mail SMTP</strong> është çaktivizuar në sajtin tuaj deri sa të ndreqni problemin. <a href="%s" target="_blank" rel="noopener noreferrer">Për të dhëna shtesë, lexoni më tepër.</a>','Your site is running an <strong>insecure version</strong> of PHP that is no longer supported. Please contact your web hosting provider to update your PHP version or switch to a <a href="%1$s" target="_blank" rel="noopener noreferrer">recommended WordPress hosting company</a>.'=>'Sajti juaj xhiron një <strong>version jo të sigurt</strong> të PHP-së, i cili nuk mbulohet më. Ju lutemi, lidhuni me shërbimin tuaj të strehimit web që të përditësojë versionin tuaj të PHP-se ose kaloni te një <a href="%1$s" target="_blank" rel="noopener noreferrer">shoqëri strehimi WordPress e rekomanduar</a>.','WP Mail SMTP Pro related message was successfully dismissed.'=>'Mesazhi i lidhur me WP Mail SMTP Pro u hodh tej me sukses.','Install and Activate'=>'Instaloje dhe Aktivizoje','Could not install a plugin. Please download from WordPress.org and install manually.'=>'S’u instalua dot shtojca. Ju lutemi, shkarkojeni prej WordPress.org dhe instalojeni dorazi.','Processing...'=>'Po përpunohet…','<strong>Bonus:</strong> WP Mail SMTP users get <span class="price-off">%s off regular price</span>, automatically applied at checkout.'=>'<strong>Bonus:</strong> përdoruesit e WP Mail SMTP përfitojnë <span class="price-off">%s ulje nga çmimi i rregullt</span>, aplikuar automatikisht gjatë përfundimit të blerjes.','<a href="%s" target="_blank" rel="noopener noreferrer">Get WP Mail SMTP Pro Today and Unlock all the Powerful Features &raquo;</a>'=>'<a href="%s" target="_blank" rel="noopener noreferrer">Merreni WP Mail SMTP Pro Që Sot dhe Çlironi krejt Veçoritë e Fuqishme &raquo;</a>','Test and verify email delivery'=>'Testoni dhe verifikoni aftësinë për dërgim email-esh','Set up domain name verification (DNS)'=>'Ujdisni verifikim emrash përkatësie (DNS)','White Glove Setup - sit back and relax while we handle everything for you'=>'Ujdisje Me Dorashka të Bardha - uluni dhe rehatohuni, teksa gjithçka e kryejmë ne për ju','Access to our world class support team'=>'Mundësinë e shfrytëzimit të ekipit tonë të klasit botëror për asistencë','Amazon SES - harness the power of AWS'=>'Amazon SES - shfrytëzoni fuqinë e AWS-s','Email Logging - keep track of every email sent from your site'=>'Regjistrim Email-esh - ndiqni çdo email dërguar prej sajtit tuaj','Manage Notifications - control which emails your site sends'=>'Administroni Njoftimet - kontrolloni çfarë email-esh dërgon sajti juaj','Pro Features:'=>'Veçori Pro:','We know that you will truly love WP Mail SMTP. It\'s used by over 4,000,000 websites.'=>'E dimë se do ta doni vërtet WP Mail SMTP-në. Përdoret nga mbi 4 milionë sajte.','Thanks for being a loyal WP Mail SMTP user. Upgrade to WP Mail SMTP Pro to unlock more awesome features and experience why WP Mail SMTP is the most popular SMTP plugin.'=>'Faleminderit që jeni një përdorues besnik i WP Mail SMTP-së. Përmirësojeni me WP Mail SMTP Pro që të çlironi më tepër veçori të goditura dhe të përjetoni pse WP Mail SMTP është shtojca më popullore për SMTP.','Get WP Mail SMTP Pro and Unlock all the Powerful Features'=>'Merrni WP Mail SMTP Pro dhe Çlironi krejt Veçoritë e Fuqishme','As a valued WP Mail SMTP Lite user you receive <strong>%s off</strong>, automatically applied at checkout!'=>'Si një përdorues i çmuar i WP Mail SMTP Lite-it përfitoni <strong>%s zbritje</strong>, aplikuar vetvetiu gjatë përfundimit të blerjes!','To unlock more features, consider <strong><a href="%s" target="_blank" rel="noopener noreferrer" class="wp-mail-smtp-upgrade-modal">upgrading to PRO</a></strong>.'=>'Për të shkyçur më tepër veçori, shihni mundësinë e <strong><a href="%s" target="_blank" rel="noopener noreferrer" class="wp-mail-smtp-upgrade-modal">përmirësimit me versionin PRO</a></strong>.','You\'re using WP Mail SMTP Lite - no license needed. Enjoy!'=>'Po përdorni WP Mail SMTP Lite - s’ka nevojë për licencë. Kënaquni!','Current provider doesn\'t support setting and forcing From Name. Emails will be sent on behalf of the account name used to setup the OAuth connection below.'=>'Shërbimi aktual nuk mbulon ujdisje dhe zbatim të detyrueshëm të Emri Nga. Email-et do të dërgohen në emër të emrit të llogarisë së përdorur për ujdisjen e lidhjes OAuth më poshtë.','Current provider will automatically force From Email to be the email address that you use to set up the OAuth connection below.'=>'Shërbimi aktual do ta bëjë vetvetiu me detyrim Emrin Nga të jetë adresa email që përdorni për ujdisjen e lidhjes OAuth më poshtë.','License Key'=>'Kyç Licence','Your license key provides access to updates and support.'=>'Kyçi juaj për licencën ju bën të mundur pasje përditësimesh dhe asistence.','License'=>'Licencë','As a valued WP Mail SMTP user, you will get <span class="price-off">%s off regular pricing</span>, automatically applied at checkout!'=>'Si një përdorues i çmuar i WP Mail SMTP-së, do të përfitoni <span class="price-off">%s ulje nga çmimi i rregullt</span>, aplikuar vetvetiu gjatë përfundimit të blerjes!','Additionally, you can take advantage of our White Glove Setup. Sit back and relax while we handle everything for you! If you simply don\'t have time or maybe you feel a bit in over your head - we got you covered.'=>'Si shtesë, mund të përfitoni nga Ujdisja jonë Me Dorashka të Bardha. Uluni dhe rehatohuni, teksa gjithçka e kryejmë ne për ju! Nëse thjesht s’keni kohë ose ndoshta ju duket paksa e ndërlikuar - kujdesemi ne.','To access our world class support, please <a href="%s" target="_blank" rel="noopener noreferrer">upgrade to WP Mail SMTP Pro</a>. Along with getting expert support, you will also get Notification controls, Email Logging, and integrations for Amazon SES, Office 365, and Outlook.com.'=>'Që të përdorni asistencën tonë të klasit botëror, ju lutemi, <a href="%s" target="_blank" rel="noopener noreferrer">përmirësojeni me WP Mail SMTP Pro-në</a>. Tok me asistencë ekspertësh, do të merrni edhe kontrolle mbi Njoftime, Regjistrim Email-sh, dhe integrim për Amazon SES, Office 365, dhe Outlook.com.','If you do not see activation email, go to your Mailgun control panel and resend the activation email.'=>'Nëse s’shihni email aktivizimi, kaloni te paneli juaj i kontrollit të Mailgun-it dhe ridërgoni email aktivizimi.','Check your inbox you used to create a Mailgun account. Click the activation link in an email from Mailgun.'=>'Kontrolloni llogarinë email që përdorët për krijimin e llogarisë Mailgun. Klikoni mbi lidhjen e aktivizimit te një email ardhur nga Mailgun.','It seems that you forgot to activate your Mailgun account.'=>'Duket se harruat të aktivizonit llogarinë tuaj Mailgun.','Enter email address where test email will be sent.'=>'Jepni adresë email ku të dërgohet email-i provë.','Priority Support'=>'Asistencë Me Përparësi','Limited Support'=>'Asistencë e Kufizuar','Complete Email Controls management for most default WordPress emails'=>'Administrim i plotë Kontrolli Email-esh për shumicën e email-eve parazgjedhje të WordPress-it','No controls over whether default WordPress emails are sent'=>'Pa kontroll nëse dërgohen apo jo email-et parazgjedhje WordPress','Emails are not logged'=>'Email-et nuk regjistrohen','Customer Support'=>'Asistencë Klienti','Email Controls'=>'Kontrolle Email-i','Bonus: WP Mail SMTP Lite users get <span class="price-off">%s off regular price</span>, automatically applied at checkout.'=>'Bonus: përdoruesit e WP Mail SMTP Lite përfitojnë <span class="price-off">%s ulje nga çmimi i rregullt</span>, i aplikuar automatikisht gjatë përfundimit të blerjes.','Get WP Mail SMTP Pro Today and Unlock all of these Powerful Features'=>'Merreni WP Mail SMTP Pro Që Sot dhe Çlironi krejt Veçoritë e Fuqishme','Pro'=>'Pro','Feature'=>'Veçori','Get the most out of WP Mail SMTP by upgrading to Pro and unlocking all of the powerful features.'=>'Përfitoni maksimumin nga WP Mail SMTP, duke e përmirësuar me versionin Pro dhe duke çliruar krejt veçoritë e fuqishme.','Plugin installed.'=>'Shtojca u instalua.','Plugin installed & activated.'=>'Shtojca u instalua & aktivizua.','Could not install the plugin.'=>'S’u instalua dot shtojca.','Plugin activated.'=>'Shtojca u aktivizua.','Could not activate the plugin. Please activate it from the Plugins page.'=>'S’u aktivizua dot shtojca. Ju lutemi, aktivizojeni që prej faqes Shtojca.','WPForms Pro'=>'WPForms Pro','Contact Forms by WPForms'=>'Formularë Kontaktesh nga WPForms','OptinMonster'=>'OptinMonster','MonsterInsights Pro'=>'MonsterInsights Pro','MonsterInsights'=>'MonsterInsights','Inactive'=>'Jo aktive','Status: %s'=>'Gjendje: %s','The WPForms Team'=>'Ekipi WPForms','The WPForms Team photo'=>'Foto e Ekipit WPForms','Yup, we know a thing or two about building awesome products that customers love.'=>'Po, dimë një a dy gjëra rreth krijimit të produkteve të mrekullueshëm që klientët i duan fort.','Our goal is to make reliable email deliverability easy for WordPress.'=>'Synimi ynë është ta bëjmë dërgimin e besueshëm të email-eve të lehtë për WordPress.','Email deliverability has been a well-documented problem for all WordPress websites. However as WPForms grew, we became more aware of this painful issue that affects our users and the larger WordPress community. So we decided to solve this problem and make a solution that\'s beginner friendly.'=>'Shkalla e dërgimit të email-eve është një problem i dokumentuar mirë për krejt sajtet WordPress. Sidoqoftë, teksa WPForms u rrit, u bëmë më të ndërgjegjshëm rreth këtij problemi të dhimbshëm që prek përdoruesit tanë dhe bashkësinë WordPress më gjerë. Ndaj vendosëm ta zgjidhim këtë problem dhe të sjellim një zgjidhje që është e lehtë për fillestarët.','Hello and welcome to WP Mail SMTP, the easiest and most popular WordPress SMTP plugin. We build software that helps your site reliably deliver emails every time.'=>'Tungjatjeta dhe mirë se vini në WP Mail SMTP, shtojca SMTP më e lehtë dhe më popullore për WordPress. Krijojmë programe që e ndihmojnë sajtin tuaj të dërgojë email-e çdo herë pa probleme.','About Us'=>'Rreth Nesh','%s vs Pro'=>'%s vs Pro','Upgrade to WP Mail SMTP Pro'=>'Përmirësojeni me WP Mail SMTP Pro','Email Log'=>'Regjistër Email-esh','%1$s \\a\\t %2$s'=>'%1$s \\a\\t %2$s','You need to save settings with Client ID and Client Secret before you can proceed.'=>'Lypset të ruani rregullimet me ID Klienti dhe të Fshehtë Klienti, përpara se të mund të ecni më tej.','Connected as %s'=>'I lidhur si %s','Please copy this URL into the "Authorized redirect URIs" field of your Google web application.'=>'Ju lutemi, kopjojeni këtë URL te fusha "URI të autorizuara ridrejtimesh", te aplikacioni juaj web Google.','The value of this field was set using a constant %1$s most likely inside %2$s of your WordPress installation.'=>'Vlera e kësaj fushe qe caktuar duke përdorur një konstante %1$s, sipas shumicës së gjasa, brenda %2$s të instalimit tuaj të WordPress-it.','All the defined constants will stop working and you will be able to change all the values on this page.'=>'Krejt konstantet e përkufizuara do të reshtin së funksionuari dhe do të jeni në gjendje t’i ndryshoni krejt vlerat te kjo faqe.','If you want to disable the use of constants, find in %1$s file the constant %2$s and turn if off:'=>'Nëse doni të çaktivizohet përdorimi i konstanteve, gjeni te kartela %1$s konstanten %2$s dhe çaktivizojeni:','To change the password you need to change the value of the constant there: %s'=>'Që të ndryshoni fjalëkalimin, lypset të ndryshoni vlerën e konstantes atje: %s','Please deactivate the free version of the WP Mail SMTP plugin before activating WP Mail SMTP Pro.'=>'Ju lutemi, çaktivizojeni versionin falas të shtojcës WP Mail SMTP, përpara se të aktivizoni WP Mail SMTP Pro.','Pepipost'=>'Pepipost','Removing the OAuth connection will give you an ability to redo the OAuth connection or link to another Google account.'=>'Heqja e lidhjes OAuth do t’ju japë aftësinë të ribëni lidhjen OAuth ose lidhni një tjetër llogari Google.','Click the button above to confirm authorization.'=>'Klikoni më sipër butonin që të ripohoni autorizimin.','Allow plugin to send emails using your Google account'=>'Lejojeni shtojcën të dërgojë email-e duke përdorur llogarinë tuaj Google','Are you sure you want to reset the current provider connection? You will need to immediately create a new one to be able to send emails.'=>'Jeni të sigurt se doni të rikthehet te parazgjedhjet lidhja e tanishme me shërbimin? Për të qenë në gjendje të dërgoni email-e, do t’ju duhet të krijoni menjëherë një të re.','Authorization'=>'Autorizim','Copy URL to clipboard'=>'Kopjoje URL-në në të papastër','Authorized redirect URI'=>'URI ridrejtimesh të autorizuara','Client Secret'=>'E fshehtë Klienti','Client ID'=>'ID Klienti','%1$s requires PHP %2$s to work and does not support your current PHP version %3$s. Please contact your host and request a PHP upgrade to the latest one.'=>'%1$s lyp PHP %2$s që të funksionojë dhe nuk mbulon versionin tuaj të tanishëm %3$s të PHP-së. Ju lutemi, lidhuni me strehuesin tuaj dhe kërkojini të përmirësojë PHP-në me versionin më të ri.','SMTP Password'=>'Fjalëkalim SMTP','SMTP Username'=>'Emër përdoruesi SMTP','By default, TLS encryption is automatically used if the server supports it (recommended). In some cases, due to server misconfigurations, this can cause issues and may need to be disabled.'=>'Si parazgjedhje, fshehtëzimi TLS përdoret automatikisht, nëse kjo mbulohet nga shërbyesi (e këshillueshme). Në disa raste, për shkak keqformësimesh shërbyesish, kjo mund të shkaktojë probleme dhe mund të duhet të çaktivizohet.','Auto TLS'=>'Auto TLS','For most servers TLS is the recommended option. If your SMTP provider offers both SSL and TLS options, we recommend using TLS.'=>'Për shumicën e shërbyesve, TLS-ja është mundësia e rekomanduar. Nëse furnizuesi juaj SMTP ofron si mundësinë SSL, ashtu edhe atë TLS, rekomandojmë përdorimin e TLS-së.','TLS'=>'TLS','SSL'=>'SSL','None'=>'Asnjë','<a href="%s" rel="" target="_blank">More information</a> on Mailgun.com.'=>'<a href="%s" rel="" target="_blank">Më tepër të dhëna</a> te Mailgun.com.','If you are operating under EU laws, you may be required to use EU region.'=>'Nëse funksiononi nën ligje të BE-së, mund të jeni të detyruar të përdorni rajonin BE.','Define which endpoint you want to use for sending messages.'=>'Përcaktoni cilin pikëmbarim dëshironi të përdoret për dërgim mesazhesh.','EU'=>'BE','US'=>'SHBA','Region'=>'Rajon','Get a Domain Name'=>'Merrni një Emër Përkatësie','Follow this link to get a Domain Name from Mailgun: %s.'=>'Ndiqni këtë lidhje që të merrni një Emër Përkatësie prej Mailgun-i: %s.','Domain Name'=>'Emër Përkatësie','Private API Key'=>'Kyç API Privat','Mailgun'=>'Mailgun','Default (none)'=>'Parazgjedhje (asnjë)','To send emails you will need only a %s access level for this API key.'=>'Që të dërgoni email-e, do t’ju duhet vetëm shkallë hyrjeje %s për këtë kyç API.','Create API Key'=>'Krijoni Kyç API','Follow this link to get an API Key from SendGrid: %s.'=>'Ndiqni këtë lidhje që të merrni një Kyç API prej SendGrid-i: %s.','API Key'=>'Kyç API','SendGrid'=>'SendGrid','Other SMTP'=>'SMTP Tjetër','Heads up! WP Mail SMTP has detected %1$s is activated. Please deactivate %1$s to prevent conflicts.'=>'Hapni sytë! WP Mail SMTP ka pikasur se %1$s është e aktivizuar. Që të parandalohen përplasje, ju lutemi, çaktivizojeni %1$s .','Please review your WP Mail SMTP settings in <a href="%s">plugin admin area</a>.'=>'Ju lutemi, shqyrtoni rregullimet tuaja për WP Mail SMTP, që nga <a href="%s">zona e përgjegjësit të shtojcave</a>.','Activated'=>'E aktivizuar','Install'=>'Instaloje','Status'=>'Gjendje','Version'=>'Version','Type'=>'Lloj','Source'=>'Burim','Active'=>'Aktiv','Not Installed'=>'E Painstaluar','Dismiss this notice'=>'Shpërfille këtë shënim','Install Plugin'=>'Instaloni Shtojcën','Please rate <strong>WP Mail SMTP</strong> <a href="%1$s" target="_blank" rel="noopener noreferrer">&#9733;&#9733;&#9733;&#9733;&#9733;</a> on <a href="%2$s" target="_blank" rel="noopener noreferrer">WordPress.org</a> to help us spread the word. Thank you from the WP Mail SMTP team!'=>'Ju lutemi, jepni një vlerësim për <strong>WP Mail SMTP</strong> <a href="%1$s" target="_blank" rel="noopener noreferrer">&#9733;&#9733;&#9733;&#9733;&#9733;</a> te <a href="%2$s" target="_blank" rel="noopener noreferrer">WordPress.org</a> që të na ndihmoni të përhapet fjala. Faleminderit prej ekipit WP Mail SMTP!','Thanks for using WP Mail SMTP! To complete the plugin setup and start sending emails, <strong>please select and configure your <a href="%s">Mailer</a></strong>.'=>'Faleminderit që përdorni WP Mail SMTP! Për të plotësuar ujdisjen e shtojcës dhe për të filluar të dërgoni email-e, <strong>ju lutemi, pëerzgjidhni dhe formësoni <a href="%s">Postuesin</a> tuaj</strong>.','You have successfully linked the current site with your Zoho Mail API project. Now you can start sending emails through Zoho Mail.'=>'E keni lidhur me sukses sajtin e tanishëm me projektin tuaj Zoho Mail API. Tani mund të filloni të dërgoni email-e përmes Zoho Mail-it.','There was an error while processing the authentication request. Please make sure that you have Client ID and Client Secret both valid and saved.'=>'Pati një gabim teksa përpunohej kërkesa e mirëfilltësimit. Ju lutemi, sigurohuni se janë të vlefshme dhe keni ruajtur si ID Klienti, ashtu edhe të Fshehtë Klienti.','There was an error while processing the authentication request. Please try again.'=>'Pati një gabim teksa kryhej kërkesa e mirëfilltësimit. Ju lutemi, riprovoni më vonë.','There was an error while processing the authentication request: %s. Please try again.'=>'Pati një gabim teksa kryhej kërkesa e mirëfilltësimit: %s. Ju lutemi, riprovoni.','If unchecked, bounce messages may be lost.'=>'Në u lëntë pa shenjë, mesazhet e rikthyer mund të humbin.','Return Path indicates where non-delivery receipts - or bounce messages - are to be sent.'=>'Shtegu u Kthimeve përcakton ku duhen dërguar dëftesa mosdërgimi - ose mesazhe kthimi.','If checked, the From Name setting above will be used for all emails, ignoring values set by other plugins.'=>'Nëse i vihet shenjë, rregullimi Emër Prej më sipër do të përdoret për krejt email-et, duke shpërfillur vlera të caktuara nga shtojca të tjera.','Force From Name'=>'Zbato Me Detyrim Emër Nga','The name that emails are sent from.'=>'Emri prej nga dërgohen email-et.','If checked, the From Email setting above will be used for all emails, ignoring values set by other plugins.'=>'Nëse i vihet shenjë, rregullimi Email Prej më sipër do të përdoret për krejt email-et, duke shpërfillur vlera të caktuara nga shtojca të tjera.','Force From Email'=>'Zbato Me Detyrim Email Nga','Please note that other plugins can change this, to prevent this use the setting below.'=>'Ju lutemi, kini parasysh se këtë mund ta ndryshojnë shtojca të tjera, që ta parandaloni këtë përdorni rregullimin më poshtë.','If you\'re using an email provider (Yahoo, Outlook.com, etc) this should be your email address for that account.'=>'Nëse përdorni një furnizues email-i (Yahoo, Outlook.com, etj) kjo do të duhej të ishte adresa juaj email për atë llogari.','The email address that emails are sent from.'=>'Adresa email prej të cilës dërgohen email-et.','Alternatively, we also offer <a href="%1$s" target="_blank" rel="noopener noreferrer">limited support</a> on the WordPress.org support forums. You can <a href="%2$s" target="_blank" rel="noopener noreferrer">create a support thread</a> there, but please understand that free support is not guaranteed and is limited to simple issues. If you have an urgent or complex issue, then please consider <a href="%3$s" target="_blank" rel="noopener noreferrer">upgrading to WP Mail SMTP Pro</a> to access our priority support ticket system.'=>'Ndryshe, ofrojmë edhe <a href="%1$s" target="_blank" rel="noopener noreferrer">asistencë të kufizuar</a> te forumet e asistencës në WordPress.org. Mund të <a href="%2$s" target="_blank" rel="noopener noreferrer">krijoni një rrjedhë asistence</a> atje, por ju lutemi të kuptoni që asistenca falas nuk është e garantuar dhe kufizohet në probleme të thjeshta. Nëse keni një problem urgjent apo të ndërlikuar, atëherë, ju lutemi, shihni mundësinë e <a href="%3$s" target="_blank" rel="noopener noreferrer">përmirësimit me WP Mail SMTP Pro</a>, për të përfituar nga sistemi ynë i asistencës me përparësi.','WP Mail SMTP is a free plugin, and the team behind WPForms maintains it to give back to the WordPress community.'=>'WP Mail SMTP është një shtojcë falas, dhe ekipi pas WPForms e mirëmban si mirënjohje ndaj bashkësisë WordPress.','As a WP Mail SMTP Pro user you have access to WP Mail SMTP priority support. Please log in to your WPMailSMTP.com account and <a href="%s" target="_blank" rel="noopener noreferrer">submit a support ticket</a>.'=>'Si përdorues i WP Mail SMTP Pro përfitoni asistencë me përparësi mbi WP Mail SMTP. Ju lutemi, bëni hyrjen te llogaria juaj në WPMailSMTP.com dhe <a href="%s" target="_blank" rel="noopener noreferrer">parashtroni një kërkesë asistence</a>.','Need support?'=>'Ju duhet asistencë?','Recommended next steps:'=>'Hapat pasues të këshilluar:','There was a problem while sending the test email.'=>'Pati një problem teksa dërgohej email-i juaj provë.','Try using a different mailer.'=>'Provoni një postues tjetër.','Contact your web hosting provider and ask them to verify your server can make outside connections. Additionally, ask them if a firewall or security policy may be preventing the connection - many shared hosts block certain ports.<br><strong>Note: this is the most common cause of this issue.</strong>'=>'Lidhuni me furnizuesin e strehimit tuaj web dhe kërkojuni të verifikojnë se shërbyesi juaj mund të bëjë lidhje jashtë. Veç kësaj, pyetini nëse lidhja mund të jetë duke u penguar nga një <em>firewall</em> se rregulla sigurie - mjaft strehë me ndarje me të tjerë bllokojnë disa porta.<br><strong>Shënim: ky është shkaku më i rëndomtë i këtij problemi.</strong>','Your host is rejecting the connection.'=>'Streha juaj nuk e pranon ndërlidhjen.','Plugin settings are incorrect (wrong SMTP settings, invalid Mailer configuration, etc).'=>'Rregullimet e shtojcës janë të pasakta (rregullime të gabuara për SMTP-në, formësim i pavlefshëm i Mailer-it, etj).','This means your test email was unable to be sent.'=>'Kjo do të thotë që s’qe e mundur të dërgohej email-i juaj provë.','An issue was detected.'=>'U pikas një problem.','Try to use a separate project for your emails, so the project has only 1 Gmail API in it enabled. You will need to remove the old project and create a new one from scratch.'=>'Provoni të përdorni një projekt ndaras për email-et tuaj, që kështu projekti të ketë vetëm 1 API Gmail të aktivizuar. Do t’ju duhet të hiqni projektin e vjetër dhe të krijoni një të ri nga e para.','You may have added a new API to a project'=>'Mund të keni shtuar një API të re te një projekt','Please follow our <a href="%s" target="_blank" rel="noopener noreferrer">Gmail tutorial</a> to be sure that all the correct project and data is applied.'=>'Ju lutemi, për t’u siguruar se janë zbatuar krejt të dhënat e sakta dhe projekti i duhur, ndiqni <a href="%s" target="_blank" rel="noopener noreferrer">përkujdesoren tonë mbi Gmail-n</a>.','Make sure that the used Client ID/Secret correspond to a proper project that has Gmail API enabled.'=>'Sigurohuni se ID/E fshehtë Klienti e përdorur i përgjigjet një projekti përkatës që ka të aktivizuar API-n Gmail.','Make sure that you have Gmail API enabled, and you can do that <a href="%s" target="_blank" rel="noopener noreferrer">here</a>.'=>'Sigurohuni se e keni të aktivizuar API-n Gmail, dhe këtë mund ta bëni nga <a href="%s" target="_blank" rel="noopener noreferrer">këtu</a>.','Make sure that Gmail app in your Google Workspace is actually enabled. You can check that in Apps list in <a href="%s" target="_blank" rel="noopener noreferrer">Google Workspace Admin</a> area.'=>'Sigurohuni se aplikacioni Gmail te Google Workspace juaj është faktikisht i aktivizuar. Këtë mund ta kontrolloni te lista e Aplikacioneve te zona <a href="%s" target="_blank" rel="noopener noreferrer">Google Workspace Admin</a>.','Make sure that your Google Workspace trial period has not expired. You can check the status <a href="%s" target="_blank" rel="noopener noreferrer">here</a>.'=>'Sigurohuni se nuk ka skaduar periudha juaj e provës së Google Workspace-it. Gjendjen mund ta kontrolloni prej <a href="%s" target="_blank" rel="noopener noreferrer">këtu</a>.','There are various reasons for that, please review the steps below.'=>'Ka arsye të ndryshme për këtë, ju lutemi, shqyrtoni hapat më poshtë.','Make sure there is no aggressive caching on site admin area pages or try to clean cache between attempts.'=>'Sigurohuni që nuk ka përdorim agresiv të fshehtinës në faqe të pjesës së përgjegjësit të sajtit ose provoni të pastroni fshehtinën mes përpjekjesh.','Reinstall the plugin with clean plugin data turned on on Misc page. This will remove all the plugin options and you will be safe to retry.'=>'Riinstaloni shtojcën, me “Pastro të dhëna shtojce” të aktivizuar te faqja Të ndryshe. Kjo do të sjellë heqjen e krejt mundësive mbi shtojcën dhe do të jeni në gjendje të riprovoni të parrezikuar.','Make sure that you are not trying to manually clean up the plugin options to retry the "Allow..." step.'=>'Sigurohuni që nuk po provoni të pastroni dorazi mundësitë mbi shtojcën, që të riprovoni hapin “Lejoje…”.','Authentication code that Google returned to you has already been used on your previous auth attempt.'=>'Kodi i mirëfilltësimit që Google ktheu për ju është përdorur tashmë në përpjekjen tuaj të mëparshme për mirëfilltësim.','Please <a href="%s" target="_blank" rel="noopener noreferrer">read this article</a> to learn more about what can cause this error and follow the steps below.'=>'Ju lutemi, për të mësuar më tepër rreth se çfarë mund ta shkaktojë këtë gabim, <a href="%s" target="_blank" rel="noopener noreferrer">lexoni këtë artikull</a> dhe ndiqni hapat më poshtë.','Unfortunately, this error can be due to many different reasons.'=>'Mjerisht, ky gabim mund të vijë për mjaft arsye të ndryshme.','Make sure that the generated email has a TO header, useful when you are responsible for email creation.'=>'Sigurohuni se email-i i prodhuar ka krye PËR, e dobishme kur jeni përgjegjës për krijimin e email-eve.','It should be something like this: %1$s. These are incorrect values: %2$s.'=>'Duhet të jetë diçka e ngjashme me: %1$s. Këto janë vlera të pasakta: %2$s.','Check the "Send To" email address used and confirm it is a valid email and was not empty.'=>'Kontrolloni adresën email të përdorur për "Dërgoje Te" dhe ripohoni se është email i vlefshëm dhe se s’qe i zbrazët.','Typically this error occurs because the address to which the email was sent to is invalid or was empty.'=>'Zakonisht ky gabim vjen ngaqë adresa ku qe dërguar email-i është e pavlefshme ose qe lënë e zbrazët.','if you are using Google Workspace, please <a href="%s" target="_blank" rel="noopener noreferrer">read this article</a> to proceed.'=>'nëse përdorni Google Workspace, ju lutemi, <a href="%s" target="_blank" rel="noopener noreferrer">lexoni këtë artikull</a> për të vazhduar.','if you are using regular Gmail account, please <a href="%s" target="_blank" rel="noopener noreferrer">read this article</a> to proceed.'=>'nëse përdorni llogari të rregullt Gmail, ju lutemi, <a href="%s" target="_blank" rel="noopener noreferrer">lexoni këtë artikull</a> për të vazhduar.','Please click "Agree", if you see that button. If not - you will need to enable less secure apps first:'=>'Nëse e shihni atë buton, ju lutemi, klikoni mbi “Pajtohem”. Nëse jo - do t’ju duhet së pari të aktivizoni aplikacione më pak të sigurta:','After the click you should be redirected to a Gmail authorization screen, where you will be asked a permission to send emails on your behalf.'=>'Pas klikimit do të duhej të ridrejtoheni te skena e autorizimit Gmail, ku do t’ju kërkohet leje për të dërguar email-e më këmbë tuajën.','Go to plugin Settings page and click the "Allow plugin to send emails using your Google account" button.'=>'Shkoni te faqja e Rregullimeve dhe klikoni mbi butonin “Lejojeni shtojcën të dërgojë email-e duke përdorur llogarinë tuaj Google”.','Make sure that you have clicked the "Allow plugin to send emails using your Google account" button under Gmail settings.'=>'Sigurohuni se keni klikuar mbi butonin "Lejoje shtojcën të dërgojë email-e duke përdorur llogarinë tuaj Google" tek rregullimet për Gmail.','You have not properly configured Gmail mailer.'=>'S’e keni formësuar si duhet postuesin e Gmail-it.','Google API Error.'=>'Gabim API Google.','Complete the steps in section "2. Verify Your Domain".'=>'Plotësoni hapin në ndarjen "2. Verifikoni Përkatësinë Tuaj".','Go to our how-to guide for setting up <a href="%s" target="_blank" rel="noopener noreferrer">Mailgun with WP Mail SMTP</a>.'=>'Shkoni te udhërrëfyesi ynë mbi ujdisjen e <a href="%s" target="_blank" rel="noopener noreferrer">Mailgun-it me WP Mail SMTP</a>.','Typically this error occurs because you have not set up and/or complete domain name verification for your Mailgun account.'=>'Zakonisht ky gabim vjen ngaqë s’keni ujdisur dhe/ose plotësuar verifikim emri përkatësie për llogarinë tuaj Mailgun.','Your Mailgun account does not have access to send emails.'=>'Llogaria juaj Mailgun nuk ka hyrje për dërgim email-esh.','Mailgun failed.'=>'Mailgun dështoi.','no'=>'jo','Contact your web hosting provider and ask them to verify your server can connect to %1$s on port %2$s using %3$s encryption. Additionally, ask them if a firewall or security policy may be preventing the connection - many shared hosts block certain ports.<br><strong>Note: this is the most common cause of this issue.</strong>'=>'Lidhuni me furnizuesin e strehimit tuaj web dhe kërkojuni të verifikojnë se shërbyesi juaj mund të lidhet te %1$s në portën%2$s duke përdorur fshehtëzim %3$s. Veç kësaj, pyetini nëse ndonjë firewall ose rregull sigurie mund të jetë duke penguar lidhjen -mjaft strehues llogarish me vend të përbashkët bllokojnë disa nga portat.<br><strong>Shënim: ky është shkaku më i rëndomtë i këtij problemi.</strong>','Triple check your SMTP settings including host address, email, and password, port, and security.'=>'Kontrolloni trefish rregullimet tuaja për SMTP-në, përfshi adresë strehe, email dhe fjalëkalim, portë, dhe siguri.','Your SMTP host is rejecting the connection.'=>'Streha juaj SMTP po hedh tej lidhjen.','Your web server is blocking the connection.'=>'Shërbyesi juaj po bllokon lidhjen.','SMTP settings are incorrect (wrong port, security setting, incorrect host).'=>'Rregullimet për SMTP-në janë të pasakta (portë e gabuar, rregullime sigurie të gabuara, strehë e pasaktë).','Typically this error is returned for one of the following reasons:'=>'Zakonisht ky gabim vjen nga një prej arsyeve vijuese:','Could not connect to the SMTP host.'=>'S’u lidh dot te strehë SMTP.','Enter correct SMTP Username (usually this is an email address) and Password in the appropriate fields.'=>'Jepni te fushat përkatëse Emër të saktë Përdoruesi SMTP (zakonisht kjo është një adresë email) dhe Fjalëkalim.','Enable Authentication'=>'Aktivizo Mirëfilltësim','Go to WP Mail SMTP plugin Settings page.'=>'Kaloni te faqja e Rregullimeve të shtojcës WP Mail SMTP.','This means the connection to your SMTP host was made successfully, but you should enable Authentication and provide correct Username and Password.'=>'Kjo do të thotë se lidhja me strehën tuaj SMTP u vendos me sukses, por se duhet të aktivizoni Mirëfilltësimin dhe të jepni Emër Përdoruesi dhe Fjalëkalim të saktë.','Unauthenticated senders are not allowed.'=>'Nuk lejohen dërgues për të cilët s’është bërë mirëfilltësimi.','Verify with them your SMTP account is in good standing and your account has not been flagged.'=>'Verifikoni me ta se llogaria juaj SMTP është në gjendje të mirë dhe se mbi nuk zbatohen kufizime.','Contact your SMTP host to ask about sending/rate limits.'=>'Lidhuni me strehuesin tuaj SMTP për t’i pyetur rreth kufizimesh dërgimi/shkalle.','Typically this error is returned when you are sending too many e-mails or e-mails that have been identified as spam.'=>'Zakonisht ky gabim vjen kur dërgoni shumë email-e ose email-e që janë identifikuar si të padëshiruar.','This means the connection to your SMTP host was made successfully, but the host rejected the email.'=>'Kjo do të thotë se lidhja me strehën tuaj SMTP u bë me sukses, por streha e hodhi poshtë email-in.','Error due to unsolicited and/or bulk e-mail.'=>'Gabim për shkak email-i të pakërkuar dhe/ose të dërguar masivisht.','Verify with your SMTP host that your account has permissions to send emails using outside connections.'=>'Verifikoni me strehën tuaj SMTP se llogaria juaj ka leje të dërgojë email-e duke përdorur lidhje të jashtme.','Contact your SMTP host to confirm you are using the correct username and password.'=>'Lidhuni me strehën tuaj SMTP që të ripohoni se po përdorni emër përdoruesi dhe fjalëkalim të saktë.','Triple check your SMTP settings including host address, email, and password. If you have recently reset your password you will need to update the settings.'=>'Kontrolloni trefish rregullimet tuaja për SMTP-në, përfshi adresë strehe, email, dhe fjalëkalim. Nëse tani afër keni ricaktuar fjalëkalimin tuaj, do t’ju duhet të përditësoni rregullimet.','Typically this error is returned when the email or password is not correct or is not what the SMTP host is expecting.'=>'Zakonisht ky gabim vjen kur email-i ose fjalëkalimi s’është i saktë ose s’është ai që pret streha SMTP.','This means we were able to connect to your SMTP host, but were not able to proceed using the email/password in the settings.'=>'Kjo do të thotë se qetë në gjendje të lidheshit me strehën tuaj SMTP, por s’qetë në gjendje të vazhdonit duke përdorur email-in/fjalëkalimin te rregullimet.','Could not authenticate your SMTP account.'=>'S’u bë dot mirëfilltësimi i llogarisë tuaj SMTP.','Contact your web hosting provider and inform them you are having issues making outbound connections.'=>'Lidhuni me furnizuesin tuaj të strehimit web dhe bëjini të ditur se po keni probleme kur bëni lidhje me jashtë.','Could not connect to your host.'=>'S’u lidh dot te streha juaj.','If using "Other SMTP" Mailer, contact your SMTP host to confirm they are accepting outside connections with the settings you have configured (address, username, port, security, etc).'=>'Nëse përdoret Postues "SMTP Tjetër", lidhuni me strehën tuaj SMTP që të ripohohet se po pranojnë lidhje me jashtë me rregullimet që keni formësuar (adresë, emër përdoruesi, portë, siguri, etj).','If using "Other SMTP" Mailer, triple check your SMTP settings including host address, email, and password.'=>'Nëse përdoret Postues "SMTP Tjetër", kontrolloni trefish rregullimet tuaja për SMTP-në, përfshi adresë, email dhe fjalëkalim.','Contact your web hosting provider and ask them to verify your server can connect to %s. Additionally, ask them if a firewall or security policy may be preventing the connection.'=>'Lidhuni me furnizuesin tuaj të strehimit web dhe kërkojuni të verifikojnë se shërbyesi juaj mund të lidhet me %s. Veç kësaj, pyetini se mos ndonjë <em>firewall</em> apo rregull sigurie mund të jetë duke penguar lidhjen.','Typically this error is returned your web server is blocking the connections or the SMTP host denying the request.'=>'Zakonisht ky gabim vjen kur shërbyesi juaj bllokon lidhjet ose kur streha SMTP nuk e pranon kërkesën.','This means your web server was unable to connect to the host server.'=>'Kjo do të thotë që shërbyesi juaj s’qe në gjendje të lidhej me shërbyesin strehë.','This means your web server was unable to connect to %s.'=>'Kjo do të thotë që shërbyesi juaj s’qe në gjendje të lidhej me %s.','Could not connect to host.'=>'S’u lidh dot te streha.','Ask them to resolve the issue then try again.'=>'Kërkojuni të zgjidhnin problemin, mandej riprovoni.','The exact error you can provide them is in the Error log, available at the bottom of this page.'=>'Gabimi i saktë të cilin mund t’ua jepni gjendet te regjistri i Gabimeve, që e keni në fund të kësaj faqeje.','Contact your web hosting provider and inform them your site has an issue with SSL certificates.'=>'Lidhuni me furnizuesin e shërbimit tuaj web dhe bëjini të ditur se sajti juaj ka një problem me dëshmitë SSL.','Typically this error is returned when web server is not configured properly.'=>'Zakonisht ky gabim vjen kur shërbyesi s’është formësuar si duhet.','This means your web server cannot reliably make secure connections (make requests to HTTPS sites).'=>'Kjo do të thotë se shërbyesi juaj s’mund të bëjë lidhje të sigurta në mënyrë të qëndrueshme (të bëjë kërkesa te sajte HTTPS).','SSL certificate issue.'=>'Problem dëshmie SSL.','Test plain text email was sent successfully! Please check your inbox to make sure it was delivered.'=>'Email-i provë si tekst i thjeshtë u dërgua me sukses! Ju lutemi, kontrolloni email-et tuaj për t’u siguruar se u dërgua.','Test email to %s'=>'Email provë për %s','Test failed. Please use a valid email address and try to resend the test email.'=>'Prova dështoi. Ju lutemi, përdorni një adresë email të vlefshme dhe provoni ta ridërgoni email-in e provës.','Send Email'=>'Dërgo Email','You cannot send an email. Mailer is not properly configured. Please check your settings.'=>'S’mund të dërgoni email. Psotuesi s’është formësuar si duhet. Ju lutemi, kontrolloni rregullimet tuaj.','Send this email in HTML or in plain text format.'=>'Dërgojeni këtë email nën format HTML ose tekst të thjeshtë.','Off'=>'Off','On'=>'On','HTML'=>'HTML','Send To'=>'Dërgoje Te','Email Test'=>'Email Provë','Settings were successfully saved.'=>'Rregullimet u ruajtën me sukses.','Save Settings'=>'Ruaji Rregullimet','Uninstall WP Mail SMTP'=>'Çinstaloje WP Mail SMTP','Hide Announcements'=>'Fshihi Lajmërimet','Test emails are allowed to be sent, regardless of this option.'=>'Email-et provë lejohen të dërgohen, pavarësisht nga kjo mundësi.','You will need to consult with their documentation to switch them to use default WordPress email delivery.'=>'Do t’ju duhet të konsultoni dokumentimin e tyre, për t’i kaluar në përdorimin e dërgimit parazgjedhje WordPress të email-eve.','Some plugins, like BuddyPress and Events Manager, are using their own email delivery solutions. By default, this option does not block their emails, as those plugins do not use default <code>wp_mail()</code> function to send emails.'=>'Disa shtojca, bie fjala, BuddyPress dhe Events Manager, përdorin zgjidhje të tyre për dërgimin e email-eve. Si parazgjedhje, kjo mundësi nuk bllokon email-et e tyre, ngaqë këto shtojca nuk përdorin funksionin parazgjedhje <code>wp_mail()</code> për dërgim email-esh.','Do Not Send'=>'Mos e Dërgo','General'=>'Të përgjithshme','Misc'=>'Të ndryshme','WPForms'=>'WPForms','Reconfigures the <code>wp_mail()</code> function to use Gmail/Mailgun/SendGrid/SMTP instead of the default <code>mail()</code> and creates an options page to manage the settings.'=>'E riformëson funksionin <code>wp_mail()</code> të përdorë Gmail/Mailgun/SendGrid/SMTP në vend se atë parazgjedhje <code>mail()</code> dhe krijon një faqe mundësish për administrim të rregullimeve.','WP Mail SMTP'=>'WP Mail SMTP','Settings'=>'Rregullime','Email'=>'Email','Send a Test Email'=>'Dërgoni një Email Provë','Save Changes'=>'Ruaji Ndryshimet','Authentication'=>'Mirëfilltësim','Encryption'=>'Fshehtëzim','SMTP Port'=>'Portë SMTP-je','SMTP Host'=>'Strehë SMTP','Return Path'=>'Shteg Kthimesh','Mailer'=>'Postues','From Name'=>'Nga Emër','From Email'=>'Nga Email']];